/* =====================================================================
   ENGINES AND TOOLS
   One guide per engine or tool, walking the same eight stages: what it is,
   how it is built, the editor, the content pipeline, building and
   deploying, licensing and cost, working with AI, and interview questions.
   Stages share the platform guides' parts: `points`, dated `facts`, an
   optional `diagram`, `deploy` steps `{t, d, shot?}` drawn as a numbered
   walkthrough, `shots` (each image credited with its licence, see
   IMAGE_LICENCES), and `iv` interview items `{q, a, follow, red}`.
   `glance` is licence and cost, languages, and target platforms.
   Engine tabs inside topics stay Godot and Unity; these guides cover the
   rest of an engine, and say so where it matters.
   ===================================================================== */
const ENGINE_STAGES = [
  ['what', 'What it is and who uses it'], ['architecture', 'How it is built'], ['editor', 'The editor'],
  ['pipeline', 'Content pipeline'], ['deploy', 'Building and deploying'], ['licence', 'Licensing and cost'],
  ['ai', 'Working with AI'], ['interview', 'Interview questions']
];
const ENGINES = [];
/** @param {string} id @param {any} o */
function ENGINE_GUIDE(id, o){ o.id = id; ENGINES.push(o); }

ENGINE_GUIDE('godot', { t:'Godot', kind:'engine', sub:'Free, open-source 2D and 3D engine, 4.x line',
  short:'An MIT-licensed engine with a small editor, text scene files and its own Python-like language. It suits indie teams, 2D games and anyone who wants to own the whole stack.',
  glance:['MIT licence, free, no royalties','GDScript, C# (.NET), C++ via GDExtension','Windows, macOS, Linux, Android, iOS, web; consoles through third parties'],
  stages:{
    what:{ points:['Godot is a general 2D and 3D engine whose editor is itself a Godot application, downloaded as a single executable.','Its 2D is a real 2D pipeline with pixel units, not 3D seen through an orthographic camera.','It suits small teams, 2D and stylised 3D games, and people who want to read or patch the engine source.','Large open-world 3D and console-first projects need more engineering in Godot than in Unreal or Unity.'],
      facts:[{ claim:'The current stable release is Godot 4.7.2, released on 18 August 2026.', asOf:'2026-09-28', src:'https://godotengine.org/download/windows/' }] },
    architecture:{ diagram:{ kind:'stack', title:'Godot, from your script to the GPU', arrow:'calls flow down',
        layers:[{t:'Your code', d:'GDScript, C# or GDExtension classes attached to nodes'},{t:'Scenes and nodes', d:'a tree of nodes, saved and instanced as scenes'},{t:'SceneTree', d:'main loop: process, physics, groups, signals'},{t:'Servers', d:'RenderingServer, PhysicsServer, AudioServer do the work'}] },
      points:['A game is a tree of nodes; a scene is a saved branch of that tree which can be instanced inside other scenes like a prefab.','The SceneTree runs the main loop, calling _process every frame and _physics_process at a fixed physics tick on each node that defines them.','Signals are the observer pattern built in: a node emits a signal and connected callables run, so children never need references to their parents.','Nodes are a convenience layer over servers; RenderingServer and PhysicsServer can be called directly for thousands of objects without node overhead.','GDScript is the built-in, optionally typed scripting language; C# runs on .NET through a separate editor build; GDExtension loads native C++ libraries without recompiling the engine.'] },
    editor:{ points:['The editor switches between 2D, 3D, Script, Game and AssetLib main screens from the top bar.','The Scene dock shows the node tree of the open scene, the FileSystem dock the res:// project folder, and the Inspector the selected node properties.','The built-in script editor has code completion and opens the class reference offline through Search Help.','The active renderer is shown and switched from the top-right corner, and changing it restarts the editor.'],
      shots:[
        { img:'assets/engines/godot-editor.webp', alt:'Godot editor showing a 3D level with the Scene, FileSystem and Inspector docks', caption:'The 3D main screen in a Godot 4.4 build: node tree top left, project files bottom left, properties on the right.', credit:{ author:'Juan Linietsky, Ariel Manzur and the Godot community', url:'https://docs.godotengine.org/en/stable/getting_started/introduction/first_look_at_the_editor.html', licence:'CC BY 3.0' },
          callouts:[{x:0.105,y:0.29,t:'Scene dock: the node tree'},{x:0.10,y:0.68,t:'FileSystem dock: res://'},{x:0.93,y:0.5,t:'Inspector'}] },
        { img:'assets/engines/godot-script.webp', alt:'Godot script editor with a GDScript CharacterBody3D movement script', caption:'The Script screen with a GDScript movement template for CharacterBody3D.', credit:{ author:'Juan Linietsky, Ariel Manzur and the Godot community', url:'https://docs.godotengine.org/en/stable/getting_started/introduction/first_look_at_the_editor.html', licence:'CC BY 3.0' },
          callouts:[{x:0.12,y:0.4,t:'Open scripts'},{x:0.12,y:0.82,t:'Methods in this script'}] }
      ] },
    pipeline:{ points:['Files dropped into the project folder are imported automatically, and import settings live beside each file in a .import sidecar.','glTF 2.0 is the recommended 3D format; imported models become scenes you can inherit from and extend.','Textures get per-file compression settings; audio imports as WAV, Ogg Vorbis or MP3, with WAV suggested for short repeated effects, Ogg Vorbis for music and speech, and MP3 where CPU is tight on mobile and web.','Scenes save as .tscn and resources as .tres, both plain text, so they diff and merge in version control.','Imported data is cached in the .godot folder, which is regenerated and should not be committed.'] },
    deploy:{ points:['Every platform needs export templates matching the exact editor version, downloaded from the editor or built from source.','Export presets per platform are saved in export_presets.cfg, and the command line can export a preset headless for CI.','Consoles are not public: the Godot Foundation ships no console templates, because console SDKs sit under NDA.'],
      deploy:[
        { t:'Install export templates', d:'Download the templates for your exact editor version from Editor, Manage Export Templates.' },
        { t:'Create presets', d:'Add a preset per platform in Project, Export, and set features, icons and included files.' },
        { t:'Desktop builds', d:'Export Windows, macOS and Linux binaries with a packed data file; macOS needs signing and notarisation to open cleanly.' },
        { t:'Android', d:'Install the Android SDK and OpenJDK 17, sign the release with your own keystore, and turn on the Gradle build to export the AAB that Google Play requires.' },
        { t:'iOS', d:'Export an Xcode project from a Mac with your Apple Team ID and bundle identifier, then archive and upload from Xcode.' },
        { t:'Web', d:'Web builds use the Compatibility renderer only; thread support needs cross-origin isolation headers, and C# projects cannot export to web.' },
        { t:'Consoles', d:'Get platform-holder approval, then port through a licensed vendor such as W4 Games under their NDA.' }
      ],
      facts:[
        { claim:'Web export supports only the Compatibility renderer (WebGL 2), and Godot 4 C# projects cannot be exported to the web.', asOf:'2026-09-28', src:'https://docs.godotengine.org/en/stable/tutorials/export/exporting_for_web.html' },
        { claim:'Threaded web builds need SharedArrayBuffer, which needs the Cross-Origin-Opener-Policy: same-origin and Cross-Origin-Embedder-Policy: require-corp headers, or the PWA service-worker workaround.', asOf:'2026-09-28', src:'https://docs.godotengine.org/en/stable/tutorials/export/exporting_for_web.html' },
        { claim:'iOS export must be done on macOS with Xcode installed, using an Apple developer Team ID and a unique bundle identifier.', asOf:'2026-09-28', src:'https://docs.godotengine.org/en/stable/tutorials/export/exporting_for_ios.html' },
        { claim:'The Godot Foundation maintains no official console ports; W4 Games offers Switch, Xbox Series and PlayStation 5 ports, and vendors such as RAWRLAB, Lone Wolf Technology and Pineapple Works also port.', asOf:'2026-09-28', src:'https://godotengine.org/consoles/' }
      ] },
    licence:{ points:['Godot is MIT-licensed: no royalties, no revenue threshold, no seat fees and no splash screen requirement.','You must include the Godot copyright and licence notice with your game, for example in the credits.','Your game content is yours; the engine licence does not cover your own assets or code.','The non-profit Godot Foundation stewards the project, and an MIT release you already use cannot be relicensed out from under you.'],
      facts:[{ claim:'Godot is released under the MIT (Expat) licence, owes no royalties, and asks games to include its copyright and licence notice; the Godot Foundation hosts the project.', asOf:'2026-09-28', src:'https://godotengine.org/license/' },
        { claim:'The renderers are Forward+ (Vulkan, Direct3D 12 or Metal, desktop), Mobile (same APIs, mobile and desktop) and Compatibility (OpenGL, low-end devices and the web).', asOf:'2026-09-28', src:'https://docs.godotengine.org/en/stable/tutorials/rendering/renderers.html' }] },
    ai:{ points:['Scenes and resources are text (.tscn, .tres, project.godot), so an agent can read, diff and edit them, though hand-editing resource ids is fragile.','The class reference is complete and versioned, and the engine source is public, so an agent can check any API against the real code.','Godot 4 renamed much of the Godot 3 API (KinematicBody to CharacterBody, yield to await, new signal syntax), and models trained on old tutorials still write Godot 3 code.','The editor runs headless from the command line, so an agent can run scripts, imports, tests and exports in CI with --headless.','Laying out scenes, tuning in the inspector, animation curves and judging how the game feels stay editor work an agent cannot see.'] },
    interview:{ iv:[
      { q:'What is the difference between a node and a scene in Godot?', a:'A node is one object with one job, such as a sprite or a collision shape. A scene is a saved tree of nodes that can be instanced many times and nested inside other scenes, which is how Godot does prefabs and composition.', follow:'How would you share behaviour between two different enemy scenes?', red:'Saying they are the same thing, or inheriting classes for everything; it shows no feel for composition by scenes.' },
      { q:'When do you use signals instead of direct method calls?', a:'Signals go up and across the tree: a child emits, and whoever cares connects, so the child never knows its parent. Direct calls go down to children you own. That keeps scenes reusable in isolation.', follow:'How do you avoid a dangling connection when a node is freed?', red:'Using get_parent() chains everywhere; scenes then break as soon as they move in the tree.' },
      { q:'What is the difference between _process and _physics_process?', a:'_process runs once per rendered frame with a variable delta. _physics_process runs at the fixed physics tick, so movement and collision code belongs there to behave the same at any frame rate.', follow:'How would you smooth a physics-driven object on a 144 Hz display?', red:'Putting movement in _process without delta; speed then depends on frame rate.' },
      { q:'Why might you choose GDScript over C#, or the reverse?', a:'GDScript is tightly integrated, reloads fast and exports everywhere, including the web. C# gives static typing, .NET libraries and faster heavy logic, but needs the .NET editor build and cannot export to the web in Godot 4.', follow:'Where would GDExtension fit instead?', red:'Claiming C# is always better; it ignores the web limitation and the integration cost.' },
      { q:'A Godot web build hangs on a blank screen on itch.io. What do you check?', a:'Whether it was exported with threads, which are off by default since Godot 4.3, because a threaded build needs cross-origin isolation headers for SharedArrayBuffer. I would enable the host setting that sends them, use the PWA workaround, or export without threads. Then I read the browser console for errors.', follow:'What does exporting without threads cost you?', red:'Blaming the browser and re-uploading; it shows no knowledge of COOP and COEP.' },
      { q:'How would you ship a Godot game on consoles?', a:'Godot has no public console templates because the SDKs are under NDA. You get approved by the platform holder, then work with a porting vendor such as W4 Games, and budget for certification like any other engine.', follow:'What in your codebase makes a port harder?', red:'Saying you just pick a console in the export dialog.' }
    ] }
  },
  flow:{ kind:'flow', title:'Godot: from project to a shipped build',
    steps:[{id:'proj', t:'Create project', d:'pick a renderer'},{id:'scenes', t:'Build scenes', d:'nodes, scripts, signals'},{id:'import', t:'Import assets', d:'glTF, textures, audio'},{id:'tpl', t:'Install templates', d:'exact editor version'},{id:'preset', t:'Export presets', d:'one per platform'},{id:'sign', t:'Sign builds', d:'keystore, Apple team, notarise'},{id:'ship', t:'Upload to stores', d:'Steam, Play, App Store, web'}],
    edges:[['proj','scenes'],['scenes','import'],['import','tpl'],['tpl','preset'],['preset','sign'],['sign','ship']] },
  topics:['platform-choice','quality-and-build-health','prototyping','ai-for-implementation']
});

ENGINE_GUIDE('unity', { t:'Unity', kind:'engine', sub:'Commercial 2D and 3D engine, Unity 6 line',
  short:'A proprietary engine with C# scripting, a huge asset and plugin ecosystem and very wide platform reach. It suits mobile studios, mid-size 3D teams and anyone who needs consoles and XR from one codebase.',
  glance:['Personal free under $200,000; Pro per seat above','C# on Mono or IL2CPP; C++ native plugins','Windows, macOS, Linux, Android, iOS, web, XR; consoles with approval'],
  stages:{
    what:{ points:['Unity is a component-based 2D and 3D engine with a closed-source runtime and editor, scripted in C#.','Its strengths are mobile, cross-platform reach and the Asset Store, which sells ready tools, shaders and art.','Unity 6 ships as yearly LTS releases with production-ready Update releases in between, numbered 6000.x.','It suits teams shipping on phones, XR headsets and consoles from one project, less so a team wanting to own the engine source.'],
      facts:[{ claim:'Unity 6.6 (6000.6) was released on 1 September 2026 as a Supported release, the last before Unity 6.7 LTS.', asOf:'2026-09-28', src:'https://discussions.unity.com/t/unity-6-6-is-now-available/1735357' },
        { claim:'Unity 6.3 is the latest LTS, supported until December 2027; Unity 6.0 LTS is supported through October 2026; LTS releases get two years, plus one more for Enterprise and Industry.', asOf:'2026-09-28', src:'https://unity.com/releases/unity-6/support' }] },
    architecture:{ diagram:{ kind:'stack', title:'Unity, from your script to the GPU', arrow:'calls flow down',
        layers:[{t:'Your code', d:'C# MonoBehaviours, ScriptableObjects or ECS systems'},{t:'GameObjects and components', d:'scenes and prefabs hold GameObjects with components'},{t:'Player loop', d:'Awake, Start, FixedUpdate, Update, LateUpdate'},{t:'Native engine', d:'C++ runtime, render pipeline (URP or HDRP), physics, audio'}] },
      points:['A scene holds GameObjects, each an empty container whose behaviour comes entirely from attached components such as Transform, Rigidbody and your scripts.','A MonoBehaviour gets lifecycle callbacks: Awake and OnEnable on load, Start before its first frame, FixedUpdate at the physics step, Update each frame, LateUpdate after all Updates, OnDestroy at teardown.','Prefabs are saved GameObject hierarchies with nesting and variants; ScriptableObjects are data assets shared by reference instead of copied per object.','C# runs on Mono with JIT compilation in the editor and some players, or on IL2CPP, which converts IL to C++ and compiles it ahead of time.','Rendering goes through a Scriptable Render Pipeline: URP for mobile to desktop, HDRP for high-end PC and consoles; the Built-In pipeline is deprecated.','DOTS is an optional data-oriented stack of Entities (ECS), the Burst compiler and the Job System, used for tens of thousands of objects rather than as the default.'] },
    editor:{ points:['The default layout has the Hierarchy of the open scene, the Project window of Assets, the Inspector and the Scene and Game views.','Play mode runs the game inside the editor, and changes made in Play mode are lost when you stop unless you copy them out.','Unity 6.6 makes Fast Enter Play Mode, which skips the domain reload, the default for new projects, so static state can survive between runs.','The Package Manager installs engine features such as URP, Input System, Addressables and Entities as versioned packages listed in Packages/manifest.json.','No editor screenshots ship with this guide, because no Unity image under a verified free licence or official press kit was found.'] },
    pipeline:{ points:['The Asset Database imports every file under Assets into a cached engine format in the Library folder, which is regenerated and never committed.','Each asset has a .meta file holding its GUID and import settings; scenes reference assets by GUID, so meta files are committed and moved with their assets.','Asset Serialization set to Force Text, the default, saves scenes, prefabs and assets as YAML that diffs in version control, though merges need care or Unity Smart Merge.','Addressables loads content by address from local or remote bundles, so builds stay small and content updates can ship without a new store build.','Per-file import settings for textures, models and audio, such as compression and max size, usually decide build size more than code does.'],
      facts:[{ claim:'A .meta file holds the asset unique ID and all its import settings; moving an asset outside Unity without its .meta breaks references.', asOf:'2026-09-28', src:'https://docs.unity3d.com/6000.6/Documentation/Manual/AssetMetadata.html' },
        { claim:'Asset Serialization Mode offers Mixed, Force Binary and Force Text, and Force Text is the default.', asOf:'2026-09-28', src:'https://docs.unity3d.com/6000.6/Documentation/Manual/class-EditorManager.html' }] },
    deploy:{ points:['Builds are configured in File, Build Profiles, which saves several independent configurations per platform, and batch mode can build them for CI.','IL2CPP is required on AOT platforms such as iOS, web and most consoles, and is the usual choice for Android release builds.','Consoles are closed: they need a Pro plan or a Preferred Platform licence key from the platform holder, and developer approval from Sony, Microsoft or Nintendo before you get the console build modules.'],
      deploy:[
        { t:'Install modules', d:'Add platform build support modules for your exact editor version in Unity Hub.' },
        { t:'Create build profiles', d:'Open File, Build Profiles, add a profile per platform, and set scenes, scripting defines and player settings overrides.' },
        { t:'Choose scripting backend', d:'Pick IL2CPP in Player settings for release builds, set code stripping, and test that reflection-heavy code survives it.' },
        { t:'Desktop builds', d:'Build Windows, macOS and Linux players; macOS builds need signing and notarisation to open without warnings.' },
        { t:'Android', d:'Target ARM64 with IL2CPP, sign with your own keystore in Publishing Settings, and build an AAB for Google Play.' },
        { t:'iOS', d:'Build an Xcode project, open it on a Mac with your Apple team and bundle identifier, then archive and upload.' },
        { t:'Web', d:'Web builds run as WebAssembly through IL2CPP, and the host must serve the compressed build files with matching headers.' },
        { t:'Consoles', d:'Get platform-holder approval, install the console build modules through each holder’s developer programme, and pass their certification.' }
      ],
      facts:[{ claim:'IL2CPP is an ahead-of-time pipeline that converts C# IL to C++ and compiles it to native code, and is required on several platforms where JIT is not available.', asOf:'2026-09-28', src:'https://docs.unity3d.com/6000.6/Documentation/Manual/scripting-backends.html' },
        { claim:'Build Profiles, opened from File, Build Profiles, save multiple independent build configurations per platform.', asOf:'2026-09-28', src:'https://docs.unity3d.com/6000.6/Documentation/Manual/build-profiles.html' },
        { claim:'Building for PlayStation, Xbox and Nintendo platforms needs an active Unity Pro subscription or a Preferred Platform licence key from the platform holder, plus developer approval from each platform holder.', asOf:'2026-09-28', src:'https://unity.com/solutions/console' },
        { claim:'The Built-In Render Pipeline is deprecated and will be made obsolete in a future release; it is supported through the Unity 6.7 LTS lifecycle.', asOf:'2026-09-28', src:'https://docs.unity3d.com/6000.6/Documentation/Manual/render-pipelines.html' }] },
    licence:{ points:['Unity is proprietary and licensed per seat; your plan is set by the revenue and funding of your company over the last 12 months.','Unity Personal is free under $200,000 of revenue and funding, and the Made with Unity splash screen is optional in Unity 6.','Unity Pro is required above $200,000 and Enterprise above $25 million, and both rose in price in 2025 and again in 2026.','In September 2023 Unity announced a per-install Runtime Fee, revised it ten days later after a developer backlash, and cancelled it in September 2024.','The lesson: a vendor engine can change its terms mid-project, so read the terms for the version you pin, review them before upgrading, and keep an exit estimate.'],
      facts:[{ claim:'Personal is free up to $200,000 revenue and funding; Pro is $2,310 per seat per year or $210 per month, required above $200,000; Enterprise is required above $25 million with custom pricing.', asOf:'2026-09-28', src:'https://unity.com/products/pricing-updates' },
        { claim:'On 12 September 2024 CEO Matt Bromberg cancelled the Runtime Fee for games, effective immediately, and raised Pro by 8% and Enterprise by 25% from 1 January 2025.', asOf:'2026-09-28', src:'https://unity.com/blog/unity-is-canceling-the-runtime-fee' },
        { claim:'The per-install fee announced in September 2023 was due from 1 January 2024; the 22 September 2023 open letter exempted Personal, limited it to the next LTS shipping in 2024 onward, exempted games under $1 million in revenue, and let studios pay the lesser of 2.5% of revenue or the install-based fee.', asOf:'2026-09-28', src:'https://unity.com/blog/an-open-letter-to-our-community' }] },
    ai:{ points:['With Force Text, scenes and prefabs are YAML an agent can read, but they reference assets by GUID and fileID, so hand edits easily break links.','C# and the scripting API are heavily documented and well represented in training data, so agents write MonoBehaviour code fluently.','Training data mixes eras: the old Input Manager versus the Input System, Built-In versus URP shaders, and pre-6 APIs, so check code against the versioned docs.','The editor runs headless with -batchmode, -executeMethod and -runTests, so an agent can run builds and tests from CI without the GUI.','Wiring references in the Inspector, lighting, animation and feel stay editor work an agent cannot see or verify.'] },
    interview:{ iv:[
      { q:'What is the order of Awake, OnEnable, Start and Update, and why does it matter?', a:'Awake runs when the object loads, then OnEnable, then Start just before its first Update, then Update every frame. Initialise your own state in Awake and read other objects in Start, because Awake order between objects is not guaranteed.', follow:'How would you force one script to run before another?', red:'Doing cross-object lookups in Awake; it works by luck until load order changes.' },
      { q:'When do you pick IL2CPP over Mono?', a:'IL2CPP is mandatory on iOS, web and most consoles and is the norm for Android release builds, giving native AOT code. Mono builds faster, so it suits iteration. IL2CPP stripping can remove code used only through reflection, so you add link.xml or Preserve attributes.', follow:'How would you debug a crash that only happens in IL2CPP builds?', red:'Saying there is no difference; it ignores AOT limits and code stripping.' },
      { q:'Why do .meta files matter in version control?', a:'They hold each asset GUID and import settings, and every reference in scenes and prefabs points to that GUID. Losing or regenerating a meta file breaks those links, so meta files are committed and moved with their assets.', follow:'How do you handle merge conflicts in scene YAML?', red:'Putting meta files in .gitignore; the team then gets missing references on every pull.' },
      { q:'URP or HDRP for a new project?', a:'URP for anything that ships on mobile, Switch or web, or wants one pipeline across platforms. HDRP only for high-end PC and current consoles where the visual target needs it. The Built-In pipeline is deprecated, so I would not start new work on it.', follow:'What breaks when you migrate an old project to URP?', red:'Picking HDRP for a mobile game because it looks better.' },
      { q:'What did the 2023 Runtime Fee teach studios?', a:'Unity announced a per-install fee, revised it within ten days and cancelled it a year later. An engine licence is a dependency with risk, so studios read the terms for the version they pin, track changes and keep an estimate of what a port would cost.', follow:'How would that change your engine choice for a new project?', red:'Saying it no longer matters because it was cancelled; the terms can still change.' },
      { q:'When would you use DOTS instead of GameObjects?', a:'When you simulate tens of thousands of similar entities, such as crowds or projectiles, and GameObject overhead shows in the profiler. Otherwise GameObjects are simpler and better supported by tools, and the two can be mixed.', follow:'What does the Burst compiler add?', red:'Rewriting a whole small game in ECS for speed with no profiling.' }
    ] }
  },
  flow:{ kind:'flow', title:'Unity: from project to a shipped build',
    steps:[{id:'proj', t:'Create project', d:'URP or HDRP template'},{id:'scenes', t:'Build scenes', d:'GameObjects, prefabs, C#'},{id:'assets', t:'Import assets', d:'meta files, Force Text'},{id:'addr', t:'Addressables', d:'group remote content'},{id:'profile', t:'Build profiles', d:'one per platform'},{id:'il2cpp', t:'IL2CPP build', d:'strip and test'},{id:'sign', t:'Sign builds', d:'keystore, Apple team, notarise'},{id:'ship', t:'Upload to stores', d:'Steam, Play, App Store, consoles'}],
    edges:[['proj','scenes'],['scenes','assets'],['assets','addr'],['addr','profile'],['profile','il2cpp'],['il2cpp','sign'],['sign','ship']] },
  topics:['platform-choice','business-model','quality-and-build-health','ai-for-implementation','pm-risk']
});

ENGINE_GUIDE('gamemaker', { t:'GameMaker', kind:'engine', sub:'2D-first engine from YoYo Games, part of Opera',
  short:'A 2D-focused engine built around objects, events and rooms, scripted in GML or the block-based GML Visual. It suits solo developers and small teams shipping 2D games fast.',
  glance:['Free for non-commercial use; $99.99 one-time Professional; Enterprise subscription for consoles','GML Code and GML Visual','Windows, macOS, Ubuntu, HTML5, GX.games, Android, iOS, tvOS; consoles on Enterprise'],
  stages:{
    what:{ points:['GameMaker is a 2D-first engine and IDE whose whole design assumes sprites, tiles and rooms rather than meshes and scenes.','It ships two release channels: an LTS build that only gets critical fixes and a Beta that gets features first.','It suits solo developers and small teams making action, platformer and RPG games in 2D who want a short path to a playable build.','There is no 3D level editor, so 3D work happens only through code and shaders and, arguably, fights the tool.','Shipped games include Undertale, Hotline Miami, Hyper Light Drifter and Chicory: A Colorful Tale.'],
      facts:[{ claim:'The default release is LTS 2026.0.0 (May 2026); the Beta channel is at 2026.100 (from July 2026), and the Monthly 2024 series was superseded by LTS 2026.0.', asOf:'2026-09-28', src:'https://releases.gamemaker.io/' },
        { claim:'The LTS build has a two-year lifecycle and receives only critical bug and security fixes; Beta receives fixes and features sooner.', asOf:'2026-09-28', src:'https://gamemaker.io/en/download' },
        { claim:'Hotline Miami by Dennaton Games was developed with GameMaker.', asOf:'2026-09-28', src:'https://gamemaker.io/en/blog/hotline-miami-developed-with-gamemaker' },
        { claim:'Undertale by Toby Fox has a page in the official GameMaker showcase.', asOf:'2026-09-28', src:'https://gamemaker.io/en/showcase/undertale' },
        { claim:'Hyper Light Drifter and Chicory: A Colorful Tale are listed on the official GameMaker showcase page.', asOf:'2026-09-28', src:'https://gamemaker.io/en/showcase' }] },
    architecture:{ diagram:{ kind:'stack', title:'GameMaker, from your code to the screen', arrow:'calls flow down',
        layers:[{t:'Your GML', d:'code or GML Visual blocks inside object events'},{t:'Objects and instances', d:'objects are templates; instances live in rooms'},{t:'Rooms and the game loop', d:'step and draw events run every frame'},{t:'Runner', d:'VM runs bytecode; YYC runs compiled machine code'}] },
      points:['An object is a template and an instance is a copy of it placed in a room; changing the object changes every instance made from it afterwards.','Behaviour lives in events on the object: Create runs once, Step runs every frame, Draw renders, and Collision fires when two instances meet.','Parent objects let child objects inherit events, which is how GameMaker shares behaviour between enemy types.','A room is a level made of layers of instances, tiles and backgrounds, and the room order decides which room starts the game.','GML is a C-like scripting language; GML Visual is a drag-and-drop block editor over the same engine functions.','The VM runner builds quickly for testing; YYC compiles to machine code that runs faster but builds slower and needs the platform SDK installed.'] },
    editor:{ points:['The Asset Browser lists every sprite, object, room, script and sound in folders, and the Workspace opens their editors side by side.','The object editor shows the event list beside the GML or GML Visual editor for the selected event.','The room editor places instances and tiles on named layers, with an Inspector for each layer and instance.','The debugger runs the game with breakpoints, variable watches and a profiler for finding slow events.','No screenshots ship here: no GameMaker image with a verified reuse licence or official press kit was found.'] },
    pipeline:{ points:['Sprites are frame sequences with an origin and a collision mask set in the sprite editor.','At build time sprites, tile sets and fonts are packed onto texture pages, and texture groups decide which assets share pages to cut texture swaps.','Put assets drawn together, such as one level and its enemies, in one texture group so the GPU does not switch pages mid-frame.','The project is a .yyp root file plus a .yy file per asset, stored as JSON-like text that diffs in Git.','Two branches that both add assets tend to conflict in the shared project file, so teams coordinate asset additions.','Close the project in GameMaker before pulling or switching branches, because git operations change files the open IDE holds.'] },
    deploy:{ points:['The Free and Professional licences export to GX.games, desktop, web and mobile; only the Enterprise subscription adds console exports.','Console exports need both Enterprise and acceptance into the platform holder program, whose SDKs and tools sit under their NDA.','GX.games is the web game platform of Opera, which owns GameMaker, and it is a built-in export target.'],
      deploy:[
        { t:'Pick target and runner', d:'Choose the platform in the target manager and pick VM for fast test builds or YYC for release performance.' },
        { t:'Install SDKs', d:'Set SDK paths in Preferences for each target, since YYC and mobile builds fail without the correct toolchain.' },
        { t:'Desktop builds', d:'Build for Windows, macOS and Ubuntu; a macOS app should be signed and notarised to open cleanly.' },
        { t:'Web and GX.games', d:'Export HTML5 for your own host or itch.io, or publish directly to GX.games from the IDE.' },
        { t:'Android and iOS', d:'Sign Android with your own keystore to produce a Google Play build, and build iOS through Xcode on a Mac.' },
        { t:'Consoles', d:'Join the Nintendo, PlayStation Partners or ID@Xbox program first, then buy Enterprise and request the console export.' },
        { t:'Store upload', d:'Upload the signed build to Steam, the mobile stores or console submission and pass each platform certification.' }
      ],
      facts:[
        { claim:'Free exports to GX.games, desktop, web and mobile for non-commercial use; Professional adds a commercial licence without console; Enterprise adds console exports and source code access.', asOf:'2026-09-28', src:'https://gamemaker.io/en/get' },
        { claim:'Enterprise console targets are Nintendo Switch, PlayStation 4, PlayStation 5, Xbox One and Xbox Series X|S; mobile targets include iOS, Android, Amazon Fire, Android TV and tvOS (export overview of June 2023).', asOf:'2026-09-28', src:'https://gamemaker.io/en/blog/export-with-gamemaker' },
        { claim:'Console access requires joining the platform program (Nintendo developer, PlayStation Partners or ID@Xbox) and a monthly or yearly Enterprise subscription.', asOf:'2026-09-28', src:'https://gamemaker.io/en/help/articles/application-process-for-console-access' },
        { claim:'YYC compiles to machine code, which runs faster but takes longer to compile, and needs platform SDKs configured in Preferences.', asOf:'2026-09-28', src:'https://manual.gamemaker.io/monthly/en/Settings/YoYo_Compiler.htm' }
      ] },
    licence:{ points:['Since November 2023 GameMaker is free for non-commercial use on every non-console platform, with no watermark.','Selling a game needs the Professional licence, a one-time $99.99 purchase that replaced the earlier subscriptions.','Consoles need the Enterprise subscription, paid monthly or yearly, on top of platform-holder approval.','Opera bought YoYo Games in January 2021, so GameMaker is owned by a browser company that also runs GX.games.','The licensing lesson, arguably: a one-time fee protects the licence you bought, but the owner still sets terms for future versions such as the new GMRT runtime.'],
      facts:[
        { claim:'On 21 November 2023 GameMaker became free for non-commercial use on all non-console platforms, with a one-time commercial licence replacing the subscriptions.', asOf:'2026-09-28', src:'https://gamemaker.io/en/blog/gamemaker-free-platforms' },
        { claim:'The Professional licence costs $99.99 as a one-time purchase, with regional pricing, and console export needs Enterprise.', asOf:'2026-09-28', src:'https://gamemaker.io/en/help/articles/november-2023-pricing-terms-change-faq' },
        { claim:'Opera acquired YoYo Games, maker of GameMaker, for about $10 million on 20 January 2021 and formed Opera Gaming.', asOf:'2026-09-28', src:'https://press.opera.com/2021/01/20/opera-buys-yoyo-games-gamemaker-opera-gaming/' }
      ] },
    ai:{ facts:[{ claim:'Igor builds, runs and packages GameMaker projects from the command line for desktop, web, mobile and console targets, and can drive continuous integration through Jenkins or GitHub Actions; it needs a licence file from a prior IDE login.', asOf:'2026-09-28', src:'https://manual.gamemaker.io/lts/en/Settings/Building_via_Command_Line.htm' }],
      points:['Project files are text (.yyp and JSON-like .yy files), so an agent can read GML and diff asset metadata.','Adding assets by hand-editing .yy and .yyp files is fragile, because the IDE tracks the resource list an agent can easily break.','The online manual documents every GML function per release channel, which gives an agent a reference to check against.','GML changed a lot across GameMaker Studio 1, Studio 2 and today, so models trained on old tutorials write removed functions and old patterns.','Igor, the command-line tool in the runtime folder, builds, runs, tests and packages a project without the IDE once you have logged in once and have a licence file, so an agent or CI server can build GameMaker games.','Sprite origins, collision masks, room layouts and game feel stay editor and playtest work an agent cannot see.'] },
    interview:{ iv:[
      { q:'What is the difference between an object and an instance in GameMaker?', a:'An object is the template with its sprite, events and properties. An instance is one copy of it in a room with its own variables. Changing the object changes future instances; changing an instance touches only that copy.', follow:'How do you address all instances of one object at once?', red:'Treating them as the same thing; it leads to bugs where changing one enemy is expected to change all.' },
      { q:'When would you use VM and when YYC?', a:'VM builds fast, so I use it for daily iteration and debugging. YYC compiles to machine code and runs heavy GML faster, so I profile and ship with it. I test the YYC build before release because it is a different runner.', follow:'What would you check if a YYC build fails but VM runs fine?', red:'Always using one without reason, or never testing the release runner.' },
      { q:'How do you keep texture swaps low in a GameMaker game?', a:'Group assets drawn together into the same texture group so they share texture pages, and avoid drawing from many groups in one frame. Then I check swaps and batches in the debugger.', follow:'How would you handle a boss whose art does not fit on one page?', red:'Saying the engine handles it automatically; texture group layout is the developer’s job.' },
      { q:'How do you share behaviour between enemy types?', a:'Give them a parent object with the common events and override only the events that differ in each child. Values that vary go in variables set in the Create event.', follow:'When would you move shared logic into a script function instead?', red:'Copy-pasting code into every enemy object.' },
      { q:'How does a GameMaker team use Git safely?', a:'Commit the project text files, keep per-user files ignored, and close the project in the IDE before pulling. Coordinate who adds assets, since the shared project file conflicts when two branches add at once.', follow:'How would you resolve a conflict in the .yyp file?', red:'Pulling with the IDE open or treating the project as binary and never merging.' },
      { q:'What does shipping a GameMaker game on Switch involve?', a:'Getting approved as a Nintendo developer first, then buying the Enterprise subscription and requesting the export. Then building with Nintendo’s tools under NDA and passing certification like any engine.', follow:'What code choices make a console port easier?', red:'Saying Professional includes consoles or that you just pick Switch in the target list.' }
    ] }
  },
  flow:{ kind:'flow', title:'GameMaker: from project to a shipped build',
    steps:[{id:'proj', t:'Create project', d:'GML Code or GML Visual'},{id:'assets', t:'Sprites and rooms', d:'origins, masks, layers'},{id:'objects', t:'Objects and events', d:'Create, Step, Draw'},{id:'tex', t:'Texture groups', d:'pack pages'},{id:'runner', t:'Pick runner', d:'VM to test, YYC to ship'},{id:'sign', t:'Sign builds', d:'keystore, Apple, notarise'},{id:'ship', t:'Upload to stores', d:'Steam, stores, GX.games'}],
    edges:[['proj','assets'],['assets','objects'],['objects','tex'],['tex','runner'],['runner','sign'],['sign','ship']] },
  topics:['platform-choice','prototyping','business-model','ai-for-implementation']
});

ENGINE_GUIDE('unreal', { t:'Unreal Engine', kind:'engine', sub:'Epic Games 3D engine, Unreal Engine 5 line',
  short:'A source-available C++ engine with Blueprint visual scripting, built for high-end 3D and large teams. It suits studios shipping realistic 3D on PC and consoles, and anyone who wants the full engine source.',
  glance:['Free to use; 5% royalty above $1 million gross per product, 3.5% under Launch Everywhere with Epic','C++ and Blueprints','Windows, macOS, Linux, Android, iOS; consoles with platform-holder approval'],
  stages:{
    what:{ points:['Unreal Engine is a 3D engine from Epic Games whose full C++ source is in a private GitHub repository open to anyone who links an Epic account and accepts the EULA.','Its strengths are high-end real-time rendering, open worlds, multiplayer networking built into the gameplay framework, and tools for large teams.','Gameplay is written in C++ or in Blueprints, a node-based visual scripting language that uses the same class system.','It suits 3D studios targeting PC and consoles; small 2D or mobile-first teams often find it heavy in build size and iteration time.','This site keeps topic engine tabs to Godot and Unity; Unreal gets this guide but no tab inside the existing topics.'],
      facts:[{ claim:'Unreal Engine 5.8 was released on 17 June 2026.', asOf:'2026-09-28', src:'https://forums.unrealengine.com/t/unreal-engine-5-8-released/2729274' },
        { claim:'Hotfix 5.8.3 was released on 22 September 2026.', asOf:'2026-09-28', src:'https://forums.unrealengine.com/t/5-8-3-hotfix-released/2833315' },
        { claim:'Unreal Engine 5.8 marks MegaLights, Movie Render Graph and, for licensees, the Iris replication system as production ready, and adds Lumen Lite, a medium-quality global illumination setting that targets 60fps on PlayStation 5.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/unreal-engine/unreal-engine-5-8-release-notes' }] },
    architecture:{ diagram:{ kind:'stack', title:'Unreal, from your gameplay code to the GPU', arrow:'calls flow down',
        layers:[{t:'Your code', d:'C++ classes and Blueprints deriving from engine classes'},{t:'Gameplay framework', d:'GameMode, GameState, PlayerController, Pawn, PlayerState'},{t:'Actors and components', d:'placed in levels, streamed by World Partition'},{t:'UObject core', d:'reflection, garbage collection, serialisation, replication'},{t:'Renderer', d:'Nanite geometry, Lumen lighting, RHI to DirectX, Vulkan, Metal'}] },
      points:['Actors, components, assets and most other engine classes derive from UObject, which adds reflection through UCLASS and UPROPERTY macros, garbage collection, serialisation and Blueprint exposure.','An Actor is anything placed in a level; its behaviour and transform come from Actor Components such as StaticMeshComponent or CharacterMovementComponent.','The gameplay framework splits roles: GameMode holds the rules on the server only, PlayerController carries a player’s input and intent, and a Pawn is the body it possesses.','Use C++ for systems, performance-critical code and base classes, and Blueprints for content, tuning and level logic that designers change often.','Nanite renders virtualised high-poly meshes without hand-made LODs, Lumen gives dynamic global illumination, and World Partition streams a large world in grid cells.','The Gameplay Ability System is an optional plugin of abilities, attribute sets and gameplay effects; Epic pitches it at RPGs, action-adventure games and MOBAs, and it is arguably overkill for a small game with a few simple moves.'] },
    editor:{ points:['The default layout has the Viewport, the Outliner of actors in the level, the Details panel and the Content Browser of assets.','Play In Editor runs the game in the viewport and can simulate several clients and a listen or dedicated server for multiplayer testing.','Blueprint graphs open in their own editor, and C++ changes rebuild through your IDE or Live Coding without restarting the editor.','Plugins and project settings are enabled from the editor and stored in the .uproject file and Config .ini files, which are text.','No editor screenshots ship with this guide, because no Epic image under a stated free licence or an Epic press kit with usage terms was found.'] },
    pipeline:{ points:['Assets, levels and Blueprints are saved as .uasset and .umap binary packages, which cannot be opened as text or merged by a text merge tool.','Because binary packages cannot merge, teams lock files: Epic documents Perforce with editor checkout, and asks you to set a P4 typemap before adding files.','One File Per Actor saves each placed actor to its own file and is on by default with World Partition, so several people can edit one level.','The Derived Data Cache holds processed data such as compiled shaders; it is never committed, and a shared or cloud DDC stops each machine rebuilding it.','Git works for small teams with Git LFS and file locking, but a conflict on a binary asset still means choosing one side, never combining both.'],
      facts:[{ claim:'Epic’s Perforce guide states that .uasset files are binary and cannot be merged in a text-based tool, and that the editor checks out files so others cannot edit them concurrently.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/unreal-engine/using-perforce-as-source-control-for-unreal-engine' },
        { claim:'The DDC is not committed to version control, can be regenerated from the .uasset files, and uses the Unreal Zen Store as the local DDC by default from UE 5.4.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/unreal-engine/using-derived-data-cache-in-unreal-engine' },
        { claim:'One File Per Actor stores actor data in external files and is enabled automatically with World Partition.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/unreal-engine/one-file-per-actor-in-unreal-engine' }] },
    deploy:{ points:['Packaged builds go through the Unreal Automation Tool command BuildCookRun, whether started from the editor’s Platforms menu, the Project Launcher or RunUAT on a build machine.','Cooking converts editor assets into the target platform’s runtime formats, and it is usually the slowest step and the one that finds broken references.','BuildGraph describes a whole pipeline as an XML graph of nodes and agents that UAT runs locally or spreads across a build farm.','Console platform extension files are not on GitHub; once the platform holder has approved you and your company signs Epic’s console NDA, Epic provides them through its Developer Portal, and you build the engine from source.'],
      deploy:[
        { t:'Pick configuration', d:'Package Shipping for release, Development for testing, and set the maps and content to include in Project Settings.' },
        { t:'Build and cook', d:'Run BuildCookRun through UAT to compile the target and cook content for one platform.' },
        { t:'Stage and package', d:'UAT copies binaries and cooked content to a staging folder, then packages them in the platform’s native format.' },
        { t:'Desktop builds', d:'Package Windows, Linux or macOS; macOS builds still need signing and notarisation before players can open them.' },
        { t:'Android', d:'Install Android Studio with the SDK and NDK versions your engine release lists, sign with your keystore and package an AAB.' },
        { t:'iOS', d:'Build on a Mac with Xcode, or remotely from Windows to a Mac, with your Apple team, certificates and provisioning profile.' },
        { t:'Automate with BuildGraph', d:'Write a BuildGraph script so CI compiles, cooks, tests and packages every platform from one changelist.' },
        { t:'Consoles', d:'Get approved by Sony, Microsoft or Nintendo, request console access from Epic, sign its console NDA, build from source, then pass each holder’s certification.' }
      ],
      facts:[{ claim:'BuildCookRun runs build, cook, stage, package, deploy and run stages, started with RunUAT from Engine/Build/BatchFiles.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/unreal-engine/build-operations-cooking-packaging-deploying-and-running-projects-in-unreal-engine' },
        { claim:'BuildGraph is an XML script-based build automation system of nodes, agents and triggers that integrates with UnrealBuildTool and AutomationTool and can distribute work across a farm.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/unreal-engine/buildgraph-for-unreal-engine' },
        { claim:'Console resources are free but gated: the company must already be an approved Xbox, PlayStation or Switch developer, submit Epic’s console access request form and sign a Console NDA, and the platform extension files then come through the Epic Developer Portal, not GitHub.', asOf:'2026-09-28', src:'https://dev.epicgames.com/community/learning/knowledge-base/B9xk/getting-started-with-console-development-for-unreal-engine-and-epic-online-services' }] },
    licence:{ points:['Unreal is free to download and use, with the source available under the Unreal Engine EULA rather than an open-source licence.','Games and apps licensed to end users pay a 5% royalty on lifetime gross revenue above the first $1 million for each product.','Revenue from sales through the Epic Games Store is royalty-free and left out of the royalty calculation.','Games enrolled in Launch Everywhere with Epic, released on the Epic Games Store no later than on other stores, pay 3.5% instead of 5% on every platform, consoles included.','Since 2024, companies over $1 million in annual gross revenue that are not shipping a game or app to third-party end users buy seats instead of paying royalties.','Model the royalty in your business plan from day one, because it applies to gross revenue before store fees, not to your profit.'],
      facts:[{ claim:'A 5% royalty applies to lifetime gross revenue above $1 million directly attributable to the Unreal product, regardless of who collects it; Epic Games Store sales are royalty-free.', asOf:'2026-09-28', src:'https://www.unrealengine.com/license' },
        { claim:'Epic’s 2024 pricing set seats at $1,850 per seat per year, with regional pricing, for companies over $1 million in annual gross revenue that are not creating games; games and runtime apps licensed to end users pay royalties instead.', asOf:'2026-09-28', src:'https://www.unrealengine.com/en-US/blog/we-are-updating-unreal-engine-twinmotion-and-realitycapture-pricing-in-late-april' },
        { claim:'The Launch Everywhere with Epic programme gives a preferred royalty rate of 3.5% instead of the standard 5%, chosen on the product’s Release Form.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/dev-portal/unreal-engine/release-forms-and-royalties/release-notifications' }] },
    ai:{ points:['C++ source, .ini config and BuildGraph XML are text an agent can read and edit, and the full engine source lets it check real behaviour.','Blueprints, levels and assets are binary .uasset packages, so an agent cannot read or diff Blueprint gameplay logic as text files.','Unreal C++ is macro-heavy and arguably rarer in training data than Unity C#, so agents often misuse UPROPERTY specifiers and object ownership rules.','Training data mixes UE4 and UE5 APIs, such as the legacy input system versus Enhanced Input, so check code against the docs for your version.','UAT, BuildGraph and editor commandlets run headless from the command line, while Blueprint wiring, lighting and tuning stay editor work an agent cannot see.'] },
    interview:{ iv:[
      { q:'What are GameMode, PlayerController and Pawn for, and where does each exist in multiplayer?', a:'GameMode holds the rules and exists only on the server. PlayerController represents a player’s will and exists on the server and its owning client. The Pawn is the possessed body, replicated to everyone who can see it.', follow:'Where would you store a player’s score so all clients see it?', red:'Putting client-visible state in GameMode; clients never have one, so it never reaches them.' },
      { q:'When do you use C++ and when Blueprints?', a:'C++ for core systems, base classes, performance-critical loops and anything that needs clean diffs and review. Blueprints for content, tuning and designer-owned logic built on those classes. Most teams expose C++ classes and let Blueprints subclass them.', follow:'How do you find a slow Blueprint?', red:'Everything in Blueprints or everything in C++; both ignore who changes the code and how often.' },
      { q:'Why do Unreal teams usually use Perforce instead of plain Git?', a:'Assets are binary .uasset packages that cannot be merged, so teams need exclusive checkout, and Perforce handles large binary depots well. The editor integrates with it, and One File Per Actor reduces lock contention on levels.', follow:'What would you set up if the team insists on Git?', red:'Saying you will just merge the conflicts; binary packages cannot be merged.' },
      { q:'What is the Derived Data Cache and why does it matter to a team?', a:'It stores processed data such as compiled shaders, derived from the source assets. It is not committed, and a shared or cloud DDC means one machine builds it and everyone else fetches it instead of waiting.', follow:'Why does the first editor launch on a fresh machine take so long?', red:'Committing the DDC to source control.' },
      { q:'How does a build machine produce a packaged Unreal build?', a:'It runs UAT BuildCookRun, which compiles, cooks content for the platform, stages and packages it. For a full pipeline, BuildGraph scripts the nodes for each platform and test step, so CI runs the same graph as a developer.', follow:'Why is cooking the step that usually fails?', red:'Only packaging from the editor by hand; nothing is repeatable.' },
      { q:'How does the Unreal royalty affect a small studio’s plan?', a:'The first $1 million gross per product is free, then 5% of gross, not profit, above it, or 3.5% if it joins Launch Everywhere with Epic; Epic Games Store sales are exempt. It is due whatever the store takes, so it goes into the revenue model from the start.', follow:'How does that compare with a per-seat engine?', red:'Calculating it on net profit after store cuts.' }
    ] }
  },
  flow:{ kind:'flow', title:'Unreal Engine: from project to a shipped build',
    steps:[{id:'proj', t:'Create project', d:'C++ or Blueprint template'},{id:'vc', t:'Set up Perforce', d:'typemap, checkout, OFPA'},{id:'code', t:'Build gameplay', d:'C++ base, Blueprint content'},{id:'ddc', t:'Shared DDC', d:'shaders built once'},{id:'cook', t:'BuildCookRun', d:'build, cook, stage, package'},{id:'graph', t:'BuildGraph CI', d:'every platform per changelist'},{id:'sign', t:'Sign builds', d:'keystore, Apple team, notarise'},{id:'ship', t:'Ship to stores', d:'Steam, Epic, Play, App Store, consoles'}],
    edges:[['proj','vc'],['vc','code'],['code','ddc'],['ddc','cook'],['cook','graph'],['graph','sign'],['sign','ship']] },
  topics:['platform-choice','business-model','infra-ci-pipelines','team-and-collaboration','ai-for-implementation']
});

ENGINE_GUIDE('web', { t:'Web stack', kind:'web', sub:'HTML5 Canvas, WebGL 2 and WebGPU with open-source libraries',
  short:'Games built from browser APIs and JavaScript or TypeScript libraries such as Phaser, three.js, Babylon.js and PlayCanvas. It suits jams, prototypes, portal games and anyone who wants a link instead of an install.',
  glance:['Browser APIs free; three.js, Phaser and PlayCanvas MIT, Babylon.js Apache 2.0','JavaScript or TypeScript; WebAssembly from C, C++ or Rust','Every desktop and mobile browser; desktop and mobile stores via Electron, Tauri or Capacitor'],
  stages:{
    what:{ points:['The web stack is not one engine but browser APIs plus a library you choose: Canvas 2D, WebGL 2 or WebGPU for drawing, Web Audio for sound.','Canvas 2D draws sprites and shapes through a simple immediate API and is enough for most 2D puzzle and arcade games.','WebGL 2 is the GPU API every current browser supports; WebGPU adds compute shaders and a modern API but is not yet on by default everywhere.','Phaser is a 2D game framework, three.js is a 3D rendering library you build game code around, and Babylon.js and PlayCanvas are fuller 3D engines.','Pick Phaser for 2D games, three.js for custom 3D or visualisation, Babylon.js for a batteries-included 3D engine, and PlayCanvas for a hosted editor teams share.'],
      facts:[{ claim:'caniuse lists WebGPU as on by default in Chrome and Edge 113+, Opera 99+, Safari on iOS 26+ and Samsung Internet 24+, partial in desktop Safari 26 and off by default in Firefox, reaching about 87% of global users.', asOf:'2026-09-28', src:'https://caniuse.com/webgpu' },
        { claim:'MDN’s compatibility data records WebGPU in Chrome for Android from 121 and in Firefox from 141 as a partial implementation: on Windows since 141 and on Apple-silicon macOS since 145, but not on Linux, Intel Macs or Android.', asOf:'2026-09-28', src:'https://developer.mozilla.org/en-US/docs/Web/API/GPU' }] },
    architecture:{ diagram:{ kind:'stack', title:'A web game, from your code to the screen', arrow:'calls flow down',
        layers:[{t:'Your game code', d:'TypeScript or JavaScript scenes, entities, rules'},{t:'Library', d:'Phaser, three.js, Babylon.js or PlayCanvas'},{t:'Browser APIs', d:'Canvas 2D, WebGL 2, WebGPU, Web Audio, input'},{t:'Browser and GPU driver', d:'differs per browser, OS and phone'}] },
      points:['The frame loop is requestAnimationFrame, which calls you before each repaint and pauses in background tabs, so never drive a game with setInterval.','Run the simulation on a fixed timestep with an accumulator and render with interpolation, because frame deltas differ between 60 Hz and 120 Hz screens.','Clamp the delta after a tab returns from the background, or the accumulator runs hundreds of catch-up steps in one frame.','Load assets before the scene starts with a preloader and a progress bar, since every texture and sound is an HTTP request.','Browsers block audio until the player interacts, so create or resume the AudioContext inside the first click or tap handler.','Engine code in C, C++ or Rust compiles to WebAssembly, usually through the Emscripten toolchain, which is how Unity and Godot web exports run in a browser.'] },
    editor:{ points:['There is no single editor: most web games are written in a code editor and tested in the browser with devtools open.','Browser devtools give the profiler, memory snapshots and a network panel that shows every asset request and its size.','Tiled or LDtk supply level editing for 2D; the Babylon.js Inspector debugs a live 3D scene, and the three.js editor composes scenes you export and load.','PlayCanvas is the exception: its editor runs in the browser and several people can edit one scene at once.'],
      shots:[{ img:'assets/engines/web-threejs-lines.webp', alt:'A three.js example drawing a cube of randomly placed lines, coloured cyan to magenta by position, on black', caption:'The three.js buffer-geometry lines example: 10,000 random points in a cube joined by one line, drawn from a single BufferGeometry.', credit:{ author:'three.js authors', url:'https://github.com/mrdoob/three.js', licence:'MIT' },
        callouts:[{x:0.82,y:0.3,t:'Per-vertex colours in one BufferGeometry'}] }] },
    pipeline:{ points:['glTF 2.0, usually as a binary .glb file, is the standard 3D model format and loads directly in three.js, Babylon.js and PlayCanvas.','PNG and JPEG textures decompress to full size in GPU memory, which exhausts phone memory quickly in 3D scenes.','KTX2 files with Basis Universal compression stay compressed on the GPU and transcode at load to whatever format the device supports.','Vite serves the project with fast reload during development and bundles, minifies and hashes files for release.','Content-hashed file names let a CDN cache assets forever while a new build still reaches players at once.'] },
    deploy:{ points:['A web build is a folder of static files, so any static host or CDN can serve it with no server code.','Portals such as Poki and CrazyGames bring traffic and ads in exchange for SDK integration and, on Poki, web exclusivity.','Desktop and mobile store builds wrap the same web build in Electron, Tauri or Capacitor.','Consoles have no general web path; a web game reaches consoles only by porting to an engine the console program supports.'],
      deploy:[
        { t:'Build for release', d:'Run the bundler production build, check the output size, and test the built folder, not the dev server.' },
        { t:'Static host', d:'Push the folder to GitHub Pages, Netlify or Cloudflare Pages and serve it over HTTPS with compression.' },
        { t:'itch.io', d:'Zip the build with index.html at the root, upload it as an HTML game, and set the embed size.' },
        { t:'Web portals', d:'Add the Poki or CrazyGames SDK for loading, gameplay and ad-break events, then submit for their review.' },
        { t:'Desktop wrapper', d:'Wrap the build in Electron or Tauri to sell on Steam, and sign and notarise the macOS app.' },
        { t:'Mobile wrapper', d:'Wrap the build with Capacitor, then sign and submit through Xcode and Google Play like a native app.' },
        { t:'Test on phones', d:'Play the release build on a low-end Android phone and an iPhone before submitting anywhere.' }
      ],
      facts:[
        { claim:'Poki pays the developer 100% of revenue from players who arrive directly, through bookmarks, search, social media or the developer’s own community, and splits Poki-sourced revenue 50/50; it requires web exclusivity, which does not cover Steam, app stores or consoles.', asOf:'2026-09-28', src:'https://developers.poki.com/guide/working-with-poki' },
        { claim:'CrazyGames allows a total size of 250 MB and an initial download of 50 MB or less, 20 MB or less to qualify for the mobile homepage, and at most 1500 files.', asOf:'2026-09-28', src:'https://docs.crazygames.com/requirements/technical/' },
        { claim:'CrazyGames disables monetisation (video ads, banners and in-game purchases) during Basic Launch, a test with a limited audience lasting 7 to 21 days; revenue share starts at Full Launch.', asOf:'2026-09-28', src:'https://docs.crazygames.com/' }
      ] },
    licence:{ points:['Browser APIs are open standards, so the platform itself costs nothing and no one takes a runtime fee.','three.js, Phaser and the PlayCanvas engine are MIT: keep the copyright notice and you may ship closed-source commercial games.','Babylon.js is Apache 2.0, which is also permissive and adds an explicit patent grant and a notice for files you changed.','The hosted PlayCanvas editor is a separate service with its own plans; the MIT licence covers the engine code only.','The licensing risk moves to your assets and portals: model and texture licences and portal exclusivity terms arguably bind harder than the code.'],
      facts:[
        { claim:'three.js is released under the MIT License.', asOf:'2026-09-28', src:'https://github.com/mrdoob/three.js/blob/dev/LICENSE' },
        { claim:'Phaser is released under the MIT License, copyright Richard Davey and Phaser Studio Inc.', asOf:'2026-09-28', src:'https://github.com/phaserjs/phaser/blob/master/LICENSE.md' },
        { claim:'Babylon.js is released under the Apache License 2.0.', asOf:'2026-09-28', src:'https://github.com/BabylonJS/Babylon.js/blob/master/license.md' },
        { claim:'The PlayCanvas engine is released under the MIT License, copyright PlayCanvas Ltd.', asOf:'2026-09-28', src:'https://github.com/playcanvas/engine/blob/main/LICENSE' }
      ] },
    ai:{ points:['Everything is text: code, HTML, JSON levels and glTF scene descriptions, so an agent can read, write and diff all of it.','The game runs in a browser an agent can open headless, screenshot and read console errors from, which closes the loop without a human.','MDN and the library docs are huge and well represented in training data, so agents arguably write working Canvas and three.js code more reliably than code for most engines.','APIs still move: Phaser 4, three.js renames between releases and WebGPU are newer than much training data, so pin versions and give the agent current docs.','Agents miss browser differences: code that runs in desktop Chrome can fail in Safari on iOS, with audio unlock and WebGPU the usual breaks.','Memory and frame rate on a mid-range phone are invisible to a desktop headless run, so real-device testing stays human work.'] },
    interview:{ iv:[
      { q:'How do you structure a game loop in the browser?', a:'Use requestAnimationFrame for rendering and step the simulation on a fixed timestep with an accumulator. Render with interpolation between the last two states, and clamp the delta after a pause.', follow:'What happens when the tab is hidden?', red:'Using setInterval, or moving a fixed amount per frame so the game runs twice as fast on a 120 Hz screen, with no delta clamp for tab switches.' },
      { q:'Why does sound not play in your web game on iPhone?', a:'Browsers block audio until a user gesture. I create or resume the AudioContext in the first tap handler and show a start screen so that tap always exists.', follow:'How do you handle the context being suspended again later?', red:'Calling it a Safari bug to ignore, or autoplaying a hidden video to force it.' },
      { q:'Would you pick WebGL 2 or WebGPU for a game launching now?', a:'WebGL 2 for reach, since Firefox ships WebGPU only on Windows and Apple-silicon Macs and caniuse still rates desktop Safari partial. If I want WebGPU, I use a renderer that falls back to WebGL 2, such as three.js WebGPURenderer, and keep compute-only features optional.', follow:'What would change your answer?', red:'Choosing WebGPU only because it is newer, without checking the audience’s browsers.' },
      { q:'How do you keep a 3D web game within phone memory?', a:'Ship KTX2 textures with Basis compression so they stay compressed on the GPU, cap texture sizes, and load levels on demand. Then I measure on a real low-end phone.', follow:'How would you find a memory leak between levels?', red:'Only testing on a desktop, or assuming PNG size on disk equals GPU memory.' },
      { q:'Phaser, three.js or Babylon.js: how do you choose?', a:'Phaser for 2D, since it gives scenes, physics, input and audio. three.js when I need a flexible renderer and will write the game layer myself; Babylon.js when I want a fuller 3D engine with physics and an inspector.', follow:'What does three.js leave for you to build?', red:'Calling three.js a game engine and not planning for input, audio and game state.' },
      { q:'What does publishing on Poki cost you?', a:'SDK integration for game and ad events, and web exclusivity: no other web portals, though Steam and stores stay open. Revenue from Poki traffic is split 50/50 and direct traffic pays 100%.', follow:'How would you decide between Poki and CrazyGames?', red:'Uploading the same build to every portal without reading exclusivity terms.' }
    ] }
  },
  flow:{ kind:'flow', title:'Web stack: from project to a shipped build',
    steps:[{id:'lib', t:'Pick a library', d:'Phaser, three.js, Babylon.js'},{id:'loop', t:'Game loop', d:'rAF plus fixed timestep'},{id:'assets', t:'Assets', d:'glTF, KTX2, preload'},{id:'bundle', t:'Bundle', d:'Vite production build'},{id:'phone', t:'Test on phones', d:'Safari iOS, low-end Android'},{id:'host', t:'Host or portal', d:'static host, itch.io, Poki'},{id:'wrap', t:'Wrap for stores', d:'Electron, Tauri, Capacitor'}],
    edges:[['lib','loop'],['loop','assets'],['assets','bundle'],['bundle','phone'],['phone','host'],['phone','wrap']] },
  topics:['platform-choice','prototyping','infra-cdn-assets','ai-for-implementation','launch-and-discoverability']
});

ENGINE_GUIDE('renpy', { t:'Ren’Py', kind:'engine', sub:'Open-source visual novel engine, 8.x line',
  short:'A free engine for visual novels where the whole game is a plain-text script of labels, dialogue and menus, extended with Python. It suits writers and small teams shipping story-first games.',
  glance:['Free; MIT with LGPL-derived parts','Ren’Py script language, screen language and Python','Windows, macOS, Linux, Android, iOS and web (beta)'],
  stages:{
    what:{ points:['Ren’Py is a visual novel engine whose games are written as plain-text script files rather than built in a scene editor.','It suits writers and small teams whose game is mostly dialogue, choices, character art and music.','Anything beyond dialogue and menus, such as minigames or stat systems, is written in Python or screen language.','The original Doki Doki Literature Club ran on Ren’Py, while its Plus! edition was ported to Unity.','RPG Maker MZ, by contrast, is database- and event-driven: you fill tables and place map events, then extend it with JavaScript plugins. Its publisher, Gotcha Gotcha Games, also sells the Unity-based RPG Maker Unite.'],
      facts:[{ claim:'The current release is Ren’Py 8.5.3, released 15 May 2026; the SDK develops games for Windows, Mac and Linux, with Android and iOS tools available separately.', asOf:'2026-09-28', src:'https://www.renpy.org/latest.html' },
        { claim:'Ren’Py’s own site names the desktop version of Doki Doki Literature Club as a Ren’Py game.', asOf:'2026-09-28', src:'https://www.renpy.org/' },
        { claim:'Serenity Forge’s Zhenghua Yang says Doki Doki Literature Club Plus! was ported to Unity, begun by Unity Technologies’ programmers and finished by Serenity Forge with Team Salvato engineers.', asOf:'2026-09-28', src:'https://mcvuk.com/business-news/insisting-that-ddlc-must-be-experienced-in-one-specific-way-would-be-a-very-elitist-and-pretentious-mindset-for-us-to-have-behind-the-scenes-of-doki-doki-literature-club-plus/' },
        { claim:'RPG Maker MZ, released in summer 2020, builds games from a database of actors, skills and enemies plus menu-driven events, extended with JavaScript plugins.', asOf:'2026-09-28', src:'https://www.rpgmakerweb.com/products/rpg-maker-mz' }] },
    architecture:{ diagram:{ kind:'stack', title:'Ren’Py, from your script to the screen', arrow:'calls flow down',
        layers:[{t:'Script (.rpy)', d:'labels, say statements, menus, jumps'},{t:'Screen language', d:'UI screens: say box, menus, saves'},{t:'Python blocks', d:'init python and $ lines for logic'},{t:'Ren’Py runtime', d:'compiles .rpy to .rpyc and runs it'}] },
      points:['A game is a folder of .rpy text files that Ren’Py compiles to .rpyc on launch.','Labels mark points in the story; jump moves there for good, while call returns afterwards like a function.','A say statement is a character name and a quoted line, and a menu block turns choices into branches.','Screen language defines the interface, including the dialogue box, choice menu and save screens, as editable text.','Python runs in init python blocks at startup or in single $ lines during play, and variables declared with default are saved with the game.','The launcher, bundled with the SDK, creates projects, opens the editor, runs Lint and builds distributions.'],
      facts:[{ claim:'Labels, jump and call are documented as the core control flow of the script language.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/label.html' }] },
    editor:{ points:['Ren’Py has no visual scene editor; you write the script in a text editor that the launcher opens for you.','With config.developer on, Shift+R saves, reloads the changed script and resumes, so a writer sees edits within seconds.','The launcher lists projects and opens the game folder, the script files, Lint and the build screens.','The Interactive Director lets you add scene, show and play statements while the game runs.','No screenshots ship here: the Ren’Py documentation states no licence for its own images.'] },
    pipeline:{ points:['Images in the images folder are declared automatically by file name, so eileen happy.png becomes the image eileen happy.','Layered images build a sprite from stacked parts such as body, outfit and expression, avoiding one file per combination.','Audio plays on named channels such as music, sound and voice, with fades set in the play statement.','The translate command generates tl/<language> files with every line, so translators work in text beside the source.','Rollback lets players step back through lines and saves store the game state, so side effects outside the store break both.'],
      facts:[{ claim:'Ren’Py documents layered images for composing sprites from attribute layers.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/layeredimage.html' },
        { claim:'The translate command creates or updates translation files in tl/<language>, and extract_strings and merge_strings move existing translations to and from JSON.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/cli.html' },
        { claim:'Saving, loading and rollback are documented together, including which state is saved and how rollback interacts with Python.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/save_load_rollback.html' }] },
    deploy:{ points:['Desktop builds come straight from the launcher’s Build Distributions screen, without extra SDKs.','Android needs JDK 21 and an SDK the launcher installs; iOS needs a Mac, Xcode and Apple’s developer program.','Ren’Py documents no console target, so a console release means a port, as Doki Doki Literature Club Plus! was made in Unity.'],
      deploy:[
        { t:'Set build options', d:'Set build.name, the version and which files each package includes or excludes in options.rpy.' },
        { t:'Desktop packages', d:'Build the PC zip for Windows and Linux, and the Mac app zip for Intel and Apple Silicon.' },
        { t:'Steam', d:'Build the Markets package, set config.steam_appid, install Steam support through the launcher, and upload with Steamworks.' },
        { t:'Android', d:'Install JDK 21 and the SDK, create and back up keystores, then build a Play Bundle or a universal APK.' },
        { t:'iOS', d:'Create the Xcode project from the launcher on a Mac, set icons and signing in Xcode, then archive for App Store Connect. Recreate the project after each Ren’Py upgrade.' },
        { t:'Web', d:'Build the beta web.zip, a WebAssembly package, and upload it to itch.io or your own host.' },
        { t:'Licence notice', d:'Distribute every build in a way that satisfies the LGPL, and add the suggested notice, which the iOS docs ask for in the App Store description.' }
      ],
      facts:[
        { claim:'The launcher builds a PC zip for Windows and Linux, a Linux tar.bz2, a Mac app zip for Intel and Apple Silicon, a Windows zip, and a Markets package for itch.io and Steam.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/build.html' },
        { claim:'Steam support is installed through the launcher, is distributed only to creators accepted into the Steam partner program, and is configured with config.steam_appid.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/achievement.html' },
        { claim:'Android builds need JDK 21 and produce a Play Bundle for Google Play or a universal APK, both capped at 2 GB; the keystores must be kept to ship updates.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/android.html' },
        { claim:'iOS apps can only be created on a Mac with Xcode and membership of the Apple developer program.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/ios.html' },
        { claim:'The web platform is in beta; it cannot make arbitrary network requests or use threads, and audio waits for a player interaction.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/web.html' }
      ] },
    licence:{ points:['Ren’Py is open source and free for commercial use, and most of it is under the MIT licence.','Some parts derive from LGPL code, so every shipped game must be distributed in a way that satisfies the LGPL.','The licence page suggests a notice saying the program contains free software under licences including the LGPL, and the iOS page asks for it in the app description.','Bundled libraries carry their own licences, including Zlib, Modified BSD, Apache 2.0 and MPL 2.0.'],
      facts:[{ claim:'Most of Ren’Py is MIT-licensed; portions derive from LGPL code, so games must be distributed in a way that satisfies the LGPL.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/license.html' }] },
    ai:{ facts:[{ claim:'The command line offers lint, which checks the script for errors and prints statistics, plus compile, test, distribute, android_build and web_build.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/cli.html' },
        { claim:'Ren’Py 8.0 runs under Python 3 while 7.5 continued Python 2.7, and Ren’Py 8.4 moved to Python 3.12 on all platforms.', asOf:'2026-09-28', src:'https://www.renpy.org/doc/html/changelog.html' }],
      points:['The whole game is plain text, so an agent can read, write and diff scenes, menus, screens and Python without an editor.','Lint and builds run from the command line, so an agent can check missing labels, images and bad statements after every edit.','Lint also reports errors that would only affect players on other platforms, but the docs warn it is no substitute for thorough testing.','Ren’Py 8 moved to Python 3, so models trained on Ren’Py 7 and older tutorials may suggest Python 2 code and old patterns.','Art, sprite placement, music timing and the pacing of a line on screen are not text, so they stay human playtest work.'] },
    interview:{ iv:[
      { q:'What is the difference between jump and call in Ren’Py?', a:'Jump moves control to a label and never comes back. Call goes to a label, and a return statement brings you back to the line after the call. I use call for reusable scenes and jump for story branches.', follow:'What happens to the call stack in a save?', red:'Using them interchangeably; unmatched calls and returns make scenes replay or end the game early.' },
      { q:'Why can Python side effects break rollback?', a:'Rollback restores the store to an earlier line, but anything outside it, such as a file write or a network request, is not undone. I keep game state in store variables declared with default.', follow:'When would you use define rather than default?', red:'Saying rollback undoes everything; state outside the store drifts silently between saves.' },
      { q:'How would you localise a Ren’Py game?', a:'Run translate to generate tl/<language> files with every line keyed, have translators fill them in, and wrap interface strings in _() so they are extracted too. Re-run it after script changes to pick up new lines.', follow:'How do you handle a font that lacks the new language’s glyphs?', red:'Copying the script per language, which breaks every update.' },
      { q:'How do you avoid one image file per expression and outfit?', a:'Use a layered image with groups for body, outfit and expression, and show it with attributes. That gives every combination from a handful of files.', follow:'How do you keep the layers aligned?', red:'Exporting every combination by hand.' },
      { q:'What does shipping a Ren’Py game on Steam involve?', a:'Build the Markets package, set config.steam_appid and install Steam support from the launcher so achievements work. Then upload depots with Steamworks and include the LGPL notice.', follow:'How do you test achievements before release?', red:'Assuming achievements work without Steam support installed, or forgetting the licence notice.' },
      { q:'When would you pick RPG Maker over Ren’Py?', a:'When the game is about exploring maps and turn-based battles, because RPG Maker gives a database and event system for that out of the box. Ren’Py suits story-first games whose content is dialogue and choices in a script.', follow:'How would you add a dialogue-heavy scene in RPG Maker?', red:'Calling them interchangeable; their content models, tables versus scripts, differ.' }
    ] }
  },
  flow:{ kind:'flow', title:'Ren’Py: from project to a shipped build',
    steps:[{id:'proj', t:'Create project', d:'launcher, GUI template'},{id:'script', t:'Write script', d:'labels, say, menus'},{id:'art', t:'Images and audio', d:'layered images, channels'},{id:'lint', t:'Run Lint', d:'errors and statistics'},{id:'tl', t:'Translate', d:'tl/<language> files'},{id:'build', t:'Build distributions', d:'PC, Mac, Markets, mobile, web'},{id:'ship', t:'Upload to stores', d:'Steam, itch.io, Play, App Store'}],
    edges:[['proj','script'],['script','art'],['art','lint'],['lint','tl'],['tl','build'],['build','ship']] },
  topics:['narrative-agency','narrative-pacing','prototyping','localization-and-culture','ai-for-implementation']
});

ENGINE_GUIDE('defold', { t:'Defold', kind:'engine', sub:'Free, source-available engine from the Defold Foundation, strongest in 2D',
  short:'A lightweight engine scripted in Lua, built around collections, game objects and message passing, with very small HTML5 builds. It suits casual mobile, web and playable-ad work where download size matters.',
  glance:['Free, no royalties; Defold License derived from Apache 2.0','Lua, optional typed Lua through Teal; C++ native extensions','Windows, macOS, Linux, iOS, Android, HTML5; Switch and PlayStation for licensed developers'],
  stages:{
    what:{ points:['Defold is built as a 3D engine but is strongest in 2D, and ships as one editor download with no Xcode or Android Studio needed.','It began as a side project of two Avalanche Studios developers, was bought by King in 2014, and has been run by the Stockholm-registered Defold Foundation since 2020.','Its main selling point is size: an empty HTML5 project is a compressed download of under 1 MB on the vendor’s own table.','It suits casual mobile, web portals, instant games and playable ads, where the first load decides whether anyone plays.'],
      facts:[{ claim:'Latest stable release is Defold 1.13.1 (17 August 2026); 1.13.2 beta and 1.14.0 alpha appeared on 10 September 2026.', asOf:'2026-09-28', src:'https://github.com/defold/defold/releases' },
        { claim:'Defold was acquired by King in 2014, released free at GDC in March 2016, and its source was released and moved to the Defold Foundation in May 2020.', asOf:'2026-09-28', src:'https://defold.com/about/' },
        { claim:'On the vendor’s own table, an empty Defold 1.13.0 project with default release settings is a 0.83 MB compressed HTML5 (Wasm) download, against 11.73 MB for Unity 6.5 and 6.68 MB for Godot 4.7.1; the table header says Brotli and its footnote says gzip.', asOf:'2026-09-28', src:'https://defold.com/product/' }] },
    architecture:{ diagram:{ kind:'stack', title:'Defold, from your code to the screen', arrow:'calls flow down',
        layers:[{t:'Lua scripts', d:'init, update, on_message, on_input'},{t:'Game objects and components', d:'sprites, scripts, collision, sound'},{t:'Collections', d:'files that nest objects; proxies load worlds'},{t:'Engine', d:'C++ runtime, message dispatch, render script'}] },
      points:['A game object is an id plus a transform that holds components such as a sprite, a script or a collision object.','A collection is a file of game objects and nested collections, and it is how levels and prefabs are built.','Scripts never call each other directly; they send messages with msg.post to a URL of socket, path and fragment.','Messages are queued and delivered to on_message in several dispatch passes per frame, and a payload is capped at 2 KB.','Collection proxies load a whole new world at runtime, which is how Defold does level and menu switching.','Rendering is driven by a Lua render script, so draw order and cameras are code you own rather than editor settings.'],
      facts:[{ claim:'msg.post queues messages for asynchronous delivery to on_message, addressed as socket:/path#fragment, with a 2 KB limit on the message table and no functions allowed.', asOf:'2026-09-28', src:'https://defold.com/manuals/message-passing/' }] },
    editor:{ points:['The editor shows an Assets pane, a scene view, an Outline of the open file, and a Properties panel for the selection.','Scripts open in a built-in Lua editor with a debugger for breakpoints and variable inspection.','Hot reload pushes changed resources to a running build, including on a connected phone.','No screenshots ship here: no Defold editor image with a verified reuse licence was found.'] },
    pipeline:{ points:['Images go into atlases and tile sources, which the build packs into texture pages to keep draw calls low.','Every project file, from collections to atlases, is plain text in a readable format that diffs and merges in Git.','Libraries are added as zip URLs in game.project dependencies and fetched with a resolve step.','Native code goes in native extensions, which Defold builds on its cloud build server so you need no local toolchain.'] },
    deploy:{ points:['The editor and bob.jar bundle desktop, mobile and HTML5 from the public download.','Consoles are not in the public version: Switch and PlayStation support go to developers already licensed by the platform holder.','Steam and Facebook Instant Games are reached through extensions rather than built-in targets.'],
      deploy:[
        { t:'Set game.project', d:'Fill in title, version, icons, display size and per-platform settings in the project file.' },
        { t:'Desktop bundles', d:'Bundle Windows, macOS and Linux; sign and notarise the macOS app before distribution.' },
        { t:'Android and iOS', d:'Bundle an AAB with your keystore and an iOS IPA with your Apple certificate and provisioning profile.' },
        { t:'HTML5', d:'Bundle HTML5 and host it, or wrap it for a web portal, instant games platform or ad network.' },
        { t:'Consoles', d:'Register as a Nintendo or PlayStation developer, then request Defold through the Tools and Middleware page.' },
        { t:'Automate with bob', d:'Run bob.jar resolve, build and bundle on a CI server to produce release bundles without the editor.' }
      ],
      facts:[{ claim:'Nintendo Switch support is not in the standard version; registered Nintendo developers sign up for Defold on the Tools and Middleware page and receive the extension source, command-line bundling and a forum.', asOf:'2026-09-28', src:'https://defold.com/manuals/nintendo-switch/' },
        { claim:'Licensed PS4 and PS5 developers confirm their status on DevNet Tools and Middleware to get Defold console support, with bundling from the command line only.', asOf:'2026-09-28', src:'https://defold.com/manuals/sony-playstation/' },
        { claim:'Steam and Facebook Instant Games are supported through extensions.', asOf:'2026-09-28', src:'https://defold.com/product/' }] },
    licence:{ points:['Defold is free with no royalties, and the licence promises no subscription or licensing fees for the main product.','You may sell anything made with Defold, including with a modified engine, but you may not sell the engine or editor itself.','You must include the Defold licence and copyright notice in the games you ship.','Defold’s own site calls it source available rather than OSI open source, because the licence bans commercialising the engine and editor.'],
      facts:[{ claim:'The Defold License is derived from Apache 2.0: games may be commercialised, the editor and engine may not, and the licence and copyright notice must be included.', asOf:'2026-09-28', src:'https://defold.com/license/' },
        { claim:'Defold describes its source as available rather than Open Source: the OSI definition requires that the source can be commercialised, and the Defold Foundation chose to prevent commercialisation of the engine and editor.', asOf:'2026-09-28', src:'https://defold.com/open/' }] },
    ai:{ points:['Collections, game objects and atlases are text files, so an agent can read and edit scenes as well as scripts.','Lua is well represented in training data, but Defold APIs such as msg.post and go.animate are niche, so check each call against the API reference.','bob.jar resolves, builds and bundles from the command line, so an agent or CI can produce builds without opening the editor.','Message-passing bugs hide in code review: a wrong URL or message id fails quietly, so agents need a running build to verify.','Visual layout, atlas packing results and feel on a real phone remain editor and device work an agent cannot see.'],
      facts:[{ claim:'bob.jar resolves, builds and bundles Defold projects for desktop, iOS, Android and HTML5 from the command line and needs OpenJDK 25.', asOf:'2026-09-28', src:'https://defold.com/manuals/bob/' }] },
    interview:{ iv:[
      { q:'Why would you pick Defold for a playable ad or web game?', a:'Its empty HTML5 build is under 1 MB compressed, so load time and ad-network size caps are easier to meet. It also bundles web and mobile from one project with no extra toolchain.', follow:'What would you cut first if the build went over the network cap?', red:'Choosing it only because it is free, without mentioning size or load time.' },
      { q:'How do two scripts talk to each other in Defold?', a:'By sending a message with msg.post to the other component’s URL and handling it in on_message. Messages are queued and delivered later in the frame, and payloads are small tables up to 2 KB.', follow:'What goes wrong if you expect a reply on the next line of code?', red:'Saying you call the other script’s function directly, which Defold does not support.' },
      { q:'What is a collection proxy for?', a:'It loads a collection as a separate world at runtime, which is how you switch levels or menus and free memory. You address objects in it by the proxy’s socket name.', follow:'How would you show a loading screen while the proxy loads?', red:'Treating a proxy as the same thing as a factory that spawns one object.' },
      { q:'What does the Defold licence let you do?', a:'Ship and sell games with no royalties, even with a modified engine. You cannot sell the engine or editor, and you must include its licence notice.', follow:'How does that differ from MIT?', red:'Calling it pure open source with no conditions.' },
      { q:'How would you ship a Defold game on Switch?', a:'First become a registered Nintendo developer, then request Defold through Nintendo’s Tools and Middleware page. Console bundling then runs through the command-line tools under the platform’s terms.', follow:'What would you keep out of platform-specific code to ease the port?', red:'Saying Switch is a normal export in the public editor.' }
    ] }
  },
  flow:{ kind:'flow', title:'Defold: from project to a shipped build',
    steps:[{id:'proj', t:'game.project', d:'settings, dependencies'},{id:'coll', t:'Collections', d:'objects and components'},{id:'lua', t:'Lua scripts', d:'msg.post, on_message'},{id:'atlas', t:'Atlases', d:'pack textures'},{id:'bob', t:'Bundle', d:'editor or bob.jar'},{id:'ship', t:'Upload', d:'stores, web, ad networks'}],
    edges:[['proj','coll'],['coll','lua'],['lua','atlas'],['atlas','bob'],['bob','ship']] },
  topics:['soft-launch-and-playable-ads','platform-choice','platform-and-session']
});

ENGINE_GUIDE('cocos', { t:'Cocos Creator', kind:'engine', sub:'TypeScript 2D and 3D engine and editor, strongest in China and on mini-game platforms',
  short:'An editor and engine scripted in TypeScript, built around nodes and components, that publishes to web, native and Chinese mini-game platforms such as WeChat. It suits casual mobile and in-app games aimed at China and the ad-driven web.',
  glance:['Free; engine source under MIT, with COCOS 4 in alpha since January 2026','TypeScript','iOS, Android, Windows, macOS, web, WeChat, Douyin and other mini-game platforms, HarmonyOS'],
  stages:{
    what:{ points:['Cocos Creator is an editor plus a TypeScript engine for 2D and 3D games, from the cocos2d-x family.','It is strongest in China, where WeChat, Douyin and other super-apps host mini games that Cocos publishes to directly.','In January 2026 its owner, SUD, announced the engine’s split from the editor as COCOS 4 under MIT; its GitHub releases are still 4.0.0 alphas.','The editor download is still the 3.8 line, so most projects and tutorials today target Cocos Creator 3.8.'],
      facts:[{ claim:'The latest Cocos Creator download is 3.8.8, released 16 December 2025.', asOf:'2026-09-28', src:'https://www.cocos.com/en/creator-download' },
        { claim:'On 4 January 2026 SUD, which owns Cocos, announced COCOS 4 in a press release as fully open source under MIT, separating the engine from the editor and claiming over 1.7 million developers.', asOf:'2026-09-28', src:'https://www.prnewswire.com/news-releases/cocos-4-is-here-fully-open-source-302652264.html' },
        { claim:'The cocos4 repository is MIT-licensed, with a C++ core and TypeScript user API, targeting Windows and Android on Vulkan, macOS and iOS on Metal, and web on WebGL; its latest release is 4.0.0-alpha.34 (20 September 2026), and there is no stable 4.0.0 tag.', asOf:'2026-09-28', src:'https://github.com/cocos/cocos4/releases' }] },
    architecture:{ diagram:{ kind:'stack', title:'Cocos Creator, from your code to the screen', arrow:'calls flow down',
        layers:[{t:'TypeScript components', d:'classes decorated with @ccclass'},{t:'Nodes', d:'scene tree with transforms'},{t:'Scenes and prefabs', d:'serialized node trees'},{t:'Engine', d:'web engine or native C++ runtime'}] },
      points:['A scene is a tree of nodes, and each node has a transform plus components that give it behaviour.','A component is a TypeScript class extending Component with @ccclass, and @property exposes fields to the Inspector.','Lifecycle methods onLoad, start, update and onDestroy run on each component in a defined order.','Prefabs are reusable node trees, created at runtime with instantiate and added under a parent node.','The same TypeScript runs on the web engine in browsers and mini games, and on a C++ native runtime for app builds.'] },
    editor:{ points:['The editor has a Hierarchy of nodes, a Scene view, an Assets panel and an Inspector for the selected node’s components.','Scripts are edited in an external editor such as VS Code, and the editor recompiles TypeScript when files change.','Preview runs the game in a browser or simulator from the editor toolbar.','No screenshots ship here: no Cocos editor image with a verified reuse licence was found.'] },
    pipeline:{ points:['Assets are imported into an asset database that writes a .meta file with a UUID beside each file.','Scenes and prefabs reference assets by UUID, so moving files outside the editor breaks references.','Asset bundles split content so a build can download only what a level needs.','For size-capped targets, keep scripts in the main package and load the rest from a server, with MD5 cache names for versioning.'] },
    deploy:{ points:['The Build panel publishes native, web and mini-game targets from one project.','Each mini-game target needs its platform’s own developer tool, such as WeChat DevTools, to preview and upload.','There is no console target in the public publish list, so console work sits outside the public product.','Playable ads start from the Web Mobile build; packaging into one HTML file per ad network uses third-party tools, not a built-in target.'],
      deploy:[
        { t:'Choose platform', d:'Open the Build panel, pick the target, and set start scene, bundles and MD5 cache.' },
        { t:'Native', d:'Build iOS, Android, Windows or macOS, then sign and upload through Xcode or with your Android keystore.' },
        { t:'Web', d:'Build Web Mobile or Web Desktop and host the folder, or use it as the base of a playable ad.' },
        { t:'WeChat mini game', d:'Set the WeChat DevTools path, build, move assets to a remote server, then upload from DevTools.' },
        { t:'Other mini games', d:'Build Douyin, OPPO, vivo, Huawei or Honor targets and submit through each platform’s console.' },
        { t:'Automate', d:'Run CocosCreator with --project and --build using a saved config file on a CI server.' }
      ],
      facts:[{ claim:'Publish targets listed are iOS, Android, Huawei AppGallery Connect, HarmonyOS, Google Play, Google Play on Games, macOS, Windows, Web Mobile, Web Desktop, Facebook Instant Games, WeChat, Douyin, OPPO, vivo and Honor mini games, and Huawei Quick Games.', asOf:'2026-09-28', src:'https://docs.cocos.com/creator/manual/en/editor/publish/' },
        { claim:'The WeChat mini game package cannot exceed 4 MB including code and assets; subpackages are supported, the engine plugin is js-only, and the WebGL 2 option is experimental and forced off by default; separately, debugging WebAssembly needs base library 2.12.0 or later.', asOf:'2026-09-28', src:'https://docs.cocos.com/creator/manual/en/editor/publish/publish-wechatgame.html' },
        { claim:'The cocos-pnp plugin, maintained by an individual developer rather than Cocos, packages a Cocos 2.4 or 3.x web build into playable ads for networks including AppLovin, Facebook, Google and ironSource.', asOf:'2026-09-28', src:'https://github.com/ppgee/cocos-pnp' }] },
    licence:{ points:['The editor is a free download with no royalty charged on the games you ship.','The engine source on GitHub was already MIT-licensed in the 3.8 line; with COCOS 4, SUD says it removed the commercial clauses that Cocos Creator itself carried.','Projects on the 3.8 editor still ship under the terms that came with that download, so read them for your version.','The practical risk is platform, not price: mini-game rules and size caps are set by WeChat and each host app.'],
      facts:[{ claim:'SUD’s COCOS 4 press release says it adopts the MIT licence and removes all commercial-related clauses originally included in Cocos Creator.', asOf:'2026-09-28', src:'https://www.prnewswire.com/news-releases/cocos-4-is-here-fully-open-source-302652264.html' },
        { claim:'The cocos-engine repository’s LICENSE.md, created in December 2022, is the MIT licence, and the v3.8.8 tag carries it.', asOf:'2026-09-28', src:'https://github.com/cocos/cocos-engine/blob/v3.8.8/LICENSE.md' }] },
    ai:{ points:['TypeScript is a strong language for agents, and component code is ordinary classes with decorators.','Scenes and prefabs are JSON that references assets by UUID, so an agent can read them but hand edits easily break links.','The 2.x and 3.x APIs differ sharply: 3.x imports from the cc module instead of a global cc namespace and moves size to UITransform, so models trained on 2.x samples write wrong code.','Builds run from the command line with --build and return exit code 36 on success, so CI and agents can check results.','SUD says COCOS 4 will gradually move editor functions into a headless CLI with an AI-first pitch, but the engine is still in alpha.','Mini-game upload, review and on-device checks in WeChat DevTools stay manual work an agent cannot do.'],
      facts:[{ claim:'Command-line builds use --project and --build with platform or configPath parameters; exit code 36 means success, 32 invalid parameters, 34 a build failure.', asOf:'2026-09-28', src:'https://docs.cocos.com/creator/manual/en/editor/publish/publish-in-command-line.html' }] },
    interview:{ iv:[
      { q:'How do you fit a Cocos game under the WeChat 4 MB package cap?', a:'Keep only scripts and the first scene in the package, and load the rest from a CDN with MD5-cached names. Use subpackages or asset bundles for later levels, and measure the package after every build.', follow:'How do you keep the first screen fast while assets download?', red:'Compressing textures and hoping, with no plan for remote assets.' },
      { q:'What is the difference between a node and a component?', a:'A node is an entry in the scene tree with a transform. Components are TypeScript classes attached to nodes that give them behaviour and rendering.', follow:'How do you get another component on the same node?', red:'Putting all logic in one giant scene script.' },
      { q:'How would you build a playable ad in Cocos?', a:'Build Web Mobile, strip unused engine modules, then package it into one HTML file per ad network with a packaging tool. I test each network’s size cap and its click-to-store call.', follow:'What differs between networks?', red:'Assuming the web build is already a valid playable ad.' },
      { q:'Why do old Cocos tutorials often fail today?', a:'Version 3 replaced the global cc namespace with module imports, moved node size and anchor to UITransform, and replaced direct writes such as node.x with setPosition. I check which major version a sample targets before using it.', follow:'How would you migrate a 2.x project?', red:'Blaming the engine without checking versions.' },
      { q:'What changed with COCOS 4?', a:'In January 2026 SUD announced the engine as COCOS 4, split from the editor and under MIT with the old commercial clauses removed, and said editor functions will move to a headless CLI. Its releases are still alphas.', follow:'Would you move a live 3.8 project now?', red:'Upgrading a shipping project to a new major version without testing.' }
    ] }
  },
  flow:{ kind:'flow', title:'Cocos Creator: from project to a shipped build',
    steps:[{id:'scene', t:'Scenes and nodes', d:'hierarchy and prefabs'},{id:'ts', t:'TypeScript components', d:'@ccclass, lifecycle'},{id:'bundle', t:'Asset bundles', d:'split and remote'},{id:'build', t:'Build panel or CLI', d:'pick target'},{id:'tool', t:'Platform tool', d:'WeChat DevTools, Xcode'},{id:'ship', t:'Submit', d:'mini-game review, stores'}],
    edges:[['scene','ts'],['ts','bundle'],['bundle','build'],['build','tool'],['tool','ship']] },
  topics:['soft-launch-and-playable-ads','platform-choice','localization-and-culture']
});

ENGINE_GUIDE('blender', { t:'Blender', kind:'tool', sub:'Free, open-source 3D creation suite, 5.x line',
  short:'A GPL-licensed 3D suite for modelling, UVs, baking, rigging and animation, with a full Python API. It suits game teams of any size that want a scriptable, free asset pipeline into Godot, Unity or Unreal.',
  glance:['GPL 3.0 or later, free, no seat fees; your output is not covered by the GPL','Python (bpy) for scripts and add-ons; C and C++ in the core','Windows, macOS and Linux; exports glTF 2.0, FBX and OBJ to any engine'],
  stages:{
    what:{ points:['For a game team, Blender is where props, characters and environments are modelled, UV-unwrapped, textured, rigged and animated before export.','It is not a game engine: it has had no built-in game engine since 2.80, so every asset ends up exported to Godot, Unity or Unreal.','It suits indie teams that cannot pay Maya or 3ds Max seats, and studios that want a pipeline they can script and patch.','Studios that keep Maya for animation often run Blender beside it, which makes FBX round-trips between the two a routine part of the pipeline.'],
      facts:[{ claim:'The latest release tag is Blender 5.2.2, dated 14 September 2026; the 4.5 line is still receiving patch releases (4.5.14).', asOf:'2026-09-28', src:'https://api.github.com/repos/blender/blender/tags' }] },
    architecture:{ diagram:{ kind:'stack', title:'Blender, from your script to the file on disk', arrow:'calls flow down',
        layers:[{t:'Your Python', d:'add-ons, operators and batch scripts using bpy'},{t:'Operators and context', d:'bpy.ops acts on the active object, mode and selection'},{t:'Data blocks', d:'bpy.data: objects, meshes, materials, actions, images'},{t:'.blend file', d:'every data block saved in one binary file'}] },
      points:['Everything in a .blend file is a data block: objects, meshes, materials, images, actions and armatures, all reachable from bpy.data.','An object holds a transform and points at shared data, so many objects can use one mesh, and editing that mesh changes all of them.','Modifiers such as Mirror, Subdivision and Array are a non-destructive stack evaluated on top of the mesh, and nothing is baked in until you apply them.','The scene graph is objects parented to objects, grouped into collections; collections are also how you mark what a batch export should include.','bpy.data edits data directly and works anywhere, while bpy.ops operators depend on the current context, mode and selection, which is why headless scripts break when they rely on operators.'] },
    editor:{ points:['Workspace tabs across the top, such as Layout, Modeling, UV Editing, Texture Paint, Shading and Animation, are saved screen layouts over the same file.','The 3D Viewport, Outliner and Properties editor are where a game artist spends most of the day: scene, hierarchy and per-object settings.','The UV Editor sits beside the viewport for unwrapping, and the Shader Editor builds node materials; the glTF exporter reads Principled BSDF and unlit set-ups, so anything else has to be baked to textures first.','The Dope Sheet and its Action Editor manage animation clips as actions, which become separate named animations after glTF export.','The Text Editor and the Python Console run bpy code inside the open file, which is the fastest way to test a pipeline script.'] },
    pipeline:{ points:['Model in metres at real-world scale with Z up, and keep one object per exported mesh with its origin placed where the engine should pivot it.','Apply rotation and scale (Ctrl+A) before export, because an object scaled 0.01 in Blender arrives in the engine with 0.01 on its node transform.','Unwrap UVs, then bake high-poly detail, ambient occlusion and normals into textures on the low-poly mesh from the Bake panel in Cycles.','Rig with an armature, keep deforming bones clearly named, and store each animation as its own action so engines import them as separate clips.','glTF 2.0 is the export Godot recommends: the Khronos exporter converts to Y up by default, and its Apply Modifiers option is off by default, since applying modifiers prevents shape keys from exporting.','FBX is still the format most Unity and Unreal pipelines use, though both engines can also import glTF; Blender’s FBX exporter defaults to -Z forward and Y up, and applies modifiers by default, with scale and axis options that need testing once per engine.'] },
    deploy:{ points:['A repeatable pipeline exports from a script, not from the File menu, so every artist and CI job produces the same file with the same options.','Blender runs without a window from the command line, so a CI job can open each .blend, export it and fail the build on a Python error.','Godot can skip the export step entirely: it imports .blend files directly by calling Blender’s own glTF exporter in the background, though then every team member needs Blender installed, and the Android and web editors cannot do it.'],
      deploy:[
        { t:'Fix the conventions', d:'Agree units, axis, naming, origin placement and which collection holds exportable objects before anyone models.' },
        { t:'Write an export script', d:'Loop over the export collection in bpy and call the glTF or FBX exporter with fixed options per object or per file, or store the options as Collection Exporters on each collection and run them all with bpy.ops.wm.collection_export_all().' },
        { t:'Run it headless', d:'Call blender --background asset.blend --python-exit-code 1 --python export.py so a failing script fails the job; Blender reads arguments in order, so the exit code must come before the script.' },
        { t:'Check the output', d:'Run the Khronos glTF validator on each exported file, and check triangle counts and texture sizes against budget.' },
        { t:'Import in the engine', d:'Godot imports .blend or glTF on its own; Unity and Unreal import FBX or glTF with settings saved per asset.' },
        { t:'Pin the Blender version', d:'Install one exact Blender build on every machine and CI runner, because exporter output and the Python API change between releases.' }
      ],
      facts:[
        { claim:'-b or --background runs Blender without its interface, with audio disabled by default; -P or --python runs a script file; --python-exit-code sets an exit code from 0 to 255 when a Python exception is raised, and 0 turns it off.', asOf:'2026-09-28', src:'https://github.com/blender/blender/blob/v5.2.2/source/creator/creator_args.cc' },
        { claim:'Godot imports .blend files directly by running Blender’s glTF export behind the scenes; it needs Blender 3.0 or later (3.5 or later recommended), with the path set under Filesystem, Import, Blender, Blender Path.', asOf:'2026-09-28', src:'https://docs.godotengine.org/en/stable/tutorials/assets_pipeline/importing_3d_scenes/available_formats.html' },
        { claim:'The glTF exporter offers GLB and glTF Separate, exports +Y up by default, and leaves Apply Modifiers off by default because it prevents exporting shape keys.', asOf:'2026-09-28', src:'https://github.com/blender/blender/blob/v5.2.2/scripts/addons_core/io_scene_gltf2/__init__.py' }
      ] },
    licence:{ points:['Blender itself is GPL 3.0 or later: free to download, use commercially and redistribute, with no seats, royalties or revenue caps.','Blender’s own licence text says the GPL covers the software, not what you make with it, so models, textures, renders and exported glTF files are yours to license however you like.','Pipeline scripts you run in-house and never distribute trigger no GPL obligations, because the GPL’s conditions apply when you convey a covered work to others.','Distributing a modified Blender build means shipping its source under the GPL too, which matters if you plan to sell a custom Blender to clients.'],
      facts:[
        { claim:'Blender itself is released under the GNU General Public License 3.0 or later, © 2011-2026 Blender Foundation, and it bundles dependencies under other licences.', asOf:'2026-09-28', src:'https://github.com/blender/blender/blob/v5.2.2/release/license/license.md' },
        { claim:'The Blender readme states it can be used freely for any purpose, including commercial use and distribution.', asOf:'2026-09-28', src:'https://github.com/blender/blender/blob/v5.2.2/release/text/readme.html' },
        { claim:'GPL 3 section 2: output from running a covered work is covered by the licence only if that output, given its content, is itself a covered work.', asOf:'2026-09-28', src:'https://github.com/blender/blender/blob/v5.2.2/doc/license/GPL3-license.txt' },
        { claim:'The UPBGE manual, which carries over Blender’s game-licensing text, says the software and source code are bound to the GNU GPL but blend-files (models, textures, sounds) are not.', asOf:'2026-09-28', src:'https://upbge.org/docs/latest/manual/manual/deployment/licensing.html' }
      ] },
    ai:{ points:['Almost everything in Blender can be driven from Python through bpy, so an agent can write export scripts, batch renames, LOD generation and validation passes as plain text.','Blender runs headless with --background and --python, so an agent can run its own scripts, read the output and fix errors without anyone opening the editor.','The .blend file is binary, so an agent cannot diff or hand-edit it; it must change the file through bpy, and reviewers see the change only by running it.','Blender Lab’s own MCP server, which Claude’s Blender connector uses, and community servers such as mcp-for-blender let a model inspect the scene and run Python inside Blender; mcp-for-blender runs any Python on an unauthenticated local socket, so keep it on localhost and save your work first.','A vision model can check a rendered turntable or viewport screenshot for missing textures, flipped normals or wrong scale, which is arguably quicker than a person scanning a hundred exports.','Training data lags the API: the 2.80 rewrite changed how objects are linked to scenes and layers, and later releases keep changing operators, so pin a version and test scripts against it; clean topology, edge flow and art direction still need an artist’s hand.'],
      facts:[{ claim:'mcp-for-blender is a third-party add-on and MCP server; its execute_blender_code tool runs arbitrary Python in Blender, its README says to always save your work before using it, and its socket server has no authentication or encryption.', asOf:'2026-09-28', src:'https://github.com/ahujasid/mcp-for-blender' },
        { claim:'Claude’s Blender connector is made by Blender Lab and gives a natural-language interface to Blender’s Python API; it needs an add-on inside Blender.', asOf:'2026-09-28', src:'https://claude.com/connectors/blender' }] },
    interview:{ iv:[
      { q:'An exported character arrives in the engine 100 times too big and lying on its back. What happened?', a:'Most likely an unapplied scale and an axis mismatch: Blender is Z up in metres, glTF is Y up and many FBX pipelines assume centimetres. I would apply rotation and scale in Blender, then set the exporter axis and unit options once and save them in the export script.', follow:'How do you stop it happening again for every artist?', red:'Fixing it by scaling the object in the engine; every re-export brings the bug back.' },
      { q:'What is the difference between bpy.data and bpy.ops, and which do you use in a batch script?', a:'bpy.data edits data blocks directly and does not care about the UI. bpy.ops runs operators that depend on context, the active object, mode and selection. In headless scripts I prefer bpy.data and call operators only where there is no data-level API, such as the exporters, with the context set explicitly.', follow:'How do you override the context for an operator in a script?', red:'Using bpy.ops for everything, then being surprised when the script fails in --background.' },
      { q:'Why would you choose glTF over FBX for a Godot project?', a:'glTF 2.0 is an open, documented standard, Godot recommends it, and Blender’s exporter is maintained with Khronos. Godot can even import .blend directly by exporting glTF in the background. FBX is proprietary and its axis and scale conventions vary by tool.', follow:'When would you still use FBX?', red:'Saying the formats are the same; it shows no pipeline experience.' },
      { q:'How would you bake a high-poly sculpt onto a game-ready mesh?', a:'Make a low-poly retopology with clean UVs, place a cage or set an extrusion so rays cover the high-poly surface, and bake normals and ambient occlusion in Cycles into images at the target resolution. Then I check the result in the engine, because tangent space and green-channel conventions differ.', follow:'What causes seams in a baked normal map?', red:'Baking without checking UV overlaps or split edges, then painting over the artefacts.' },
      { q:'How would you make asset export repeatable across a team?', a:'Write one export script with fixed options, keep exportable objects in a named collection, and run it with blender --background and --python-exit-code in CI. Pin the Blender version everywhere, validate the output, and let the engine import from the generated files only.', follow:'How would you catch an asset that breaks the triangle budget?', red:'Letting every artist export by hand with their own settings.' },
      { q:'Where does AI help in a Blender pipeline, and where does it not?', a:'It is strong at writing bpy scripts, batch jobs and checks, and a vision model can review renders for obvious breakage. It is weak at topology quality, edge flow and art direction, and it often writes code for an older Blender API, so every script runs against the pinned version before it is trusted.', follow:'How would you give an agent safe access to a live Blender session?', red:'Letting an MCP tool run arbitrary Python on an unsaved production file.' }
    ] }
  },
  flow:{ kind:'flow', title:'Blender: from project to a shipped build',
    steps:[{id:'conv', t:'Set conventions', d:'units, axis, names'},{id:'model', t:'Model and UV', d:'low poly, clean UVs'},{id:'bake', t:'Bake and texture', d:'normals, AO, PBR'},{id:'rig', t:'Rig and animate', d:'armature, actions'},{id:'apply', t:'Apply transforms', d:'rotation and scale'},{id:'export', t:'Scripted export', d:'glTF or FBX, headless'},{id:'engine', t:'Engine import', d:'Godot, Unity, Unreal'}],
    edges:[['conv','model'],['model','bake'],['bake','rig'],['rig','apply'],['apply','export'],['export','engine']] },
  topics:['animation-and-vfx','infra-ci-pipelines','ai-for-implementation','verifying-ai-output']
});
